// Bundled script packs (1 total)
export const BUNDLED_SCRIPT_PACKS: Record<string, BundledScriptPack> = {
  "sdlc": {"files":{".shared/checkout.ts":"/**\n * The commit a checkout observation names.\n *\n * The engine samples the checkout when each exec node starts and hands the sample\n * to the node as `ARCHON_NODE_EXECUTION`; a binding can also carry an earlier\n * node's sample (`$<node>.execution.checkoutStart`). Reading the commit from those\n * observations, rather than running git again, means every script compares the\n * same engine-recorded facts. An observation that names no commit throws: a\n * caller bounding or pinning a review cannot guess one.\n */\n\nexport function observedCommit(label: string, value: unknown): string {\n  if (typeof value !== 'object' || value === null || Array.isArray(value)) {\n    throw new Error(`${label} is not a checkout observation`);\n  }\n  const observation = value as { kind?: unknown; commit?: unknown; reason?: unknown };\n  if (observation.kind !== 'git' || typeof observation.commit !== 'string') {\n    const reason = typeof observation.reason === 'string' ? ` (${observation.reason})` : '';\n    throw new Error(`${label} names no commit${reason}`);\n  }\n  return observation.commit;\n}\n\n/** The commit the checkout was at when this node started. */\nexport function nodeStartCommit(): string {\n  let execution: { attempt?: { checkoutStart?: unknown } };\n  try {\n    execution = JSON.parse(process.env.ARCHON_NODE_EXECUTION ?? '') as typeof execution;\n  } catch {\n    throw new Error('this node has no execution record; the engine supplies one to every exec node');\n  }\n  return observedCommit('this node start', execution.attempt?.checkoutStart ?? null);\n}\n",".shared/composition.ts":"import { createHash } from 'node:crypto';\nimport { closeSync, mkdirSync, mkdtempSync, openSync, readFileSync, writeFileSync } from 'node:fs';\nimport { arch, platform } from 'node:os';\nimport { join, resolve } from 'node:path';\nimport { projectEnvironment } from './node-env.ts';\n\nexport interface CompositionRequest {\n  /** Full commit IDs, never branch names. */\n  original_base: string;\n  base: string;\n  head: string;\n  change: string;\n  /** This identifies the entire incoming prefix, not an inferred conflicting PR. */\n  base_changes: string[];\n  method: 'merge' | 'squash';\n  check: { name: string; argv: string[]; environment: string };\n}\n\ninterface Revision {\n  commit: string;\n  tree: string;\n}\n\ninterface Subject extends Revision {\n  role: 'change-alone' | 'base-alone' | 'composition';\n}\n\ninterface Observation {\n  subject: Subject;\n  command: CompositionRequest['check'];\n  check_digest: string;\n  exit_code: number;\n  git_clean_after: boolean;\n  head_after: string;\n  log: string;\n  started_at: string;\n  finished_at: string;\n}\n\nexport interface CompositionEvidence {\n  version: 1;\n  repository: string;\n  request: CompositionRequest;\n  original_base: Revision;\n  base: Revision;\n  head: Revision;\n  merge_bases: string[] | null;\n  candidate: Revision | null;\n  runtime: { platform: string; arch: string; bun: string; git: string };\n  observations: Observation[];\n  composition: { exit_code: number; stdout: string; stderr: string } | null;\n}\n\n/**\n * Every cause archon-validate's result can carry. Only the comparison script declares\n * `interaction`: the ordinary path's classify schema and implement's omit it. Only\n * ordinary validation and implement declare `incomplete`: the comparison script\n * records an unfinished or unusable comparison as red with an empty cause.\n */\nexport const VALIDATION_RED_CAUSES = [\n  'introduced',\n  'inherited',\n  'environment',\n  'interaction',\n  'incomplete',\n  '',\n] as const;\n\nexport interface ValidationVerdict {\n  green: boolean;\n  red_cause: (typeof VALIDATION_RED_CAUSES)[number];\n  summary: string;\n}\n\nfunction object(value: unknown): Record<string, unknown> {\n  if (value === null || typeof value !== 'object' || Array.isArray(value)) {\n    throw new Error('Comparison input must be an object.');\n  }\n  return value as Record<string, unknown>;\n}\n\nfunction string(value: unknown, field: string): string {\n  if (typeof value !== 'string' || value.trim() === '' || value.includes('\\0')) {\n    throw new Error(`Comparison ${field} must be a nonempty string without NUL bytes.`);\n  }\n  return value;\n}\n\nfunction strings(value: unknown, field: string): string[] {\n  if (!Array.isArray(value)) throw new Error(`Comparison ${field} must be an array.`);\n  return value.map((item: unknown) => string(item, field));\n}\n\nexport function parseCompositionRequest(value: unknown): CompositionRequest {\n  const input = object(value);\n  const check = object(input.check);\n  if (input.method !== 'merge' && input.method !== 'squash') {\n    throw new Error(\n      'Comparison method must be merge or squash; rebase requires different evidence.'\n    );\n  }\n  const argv = strings(check.argv, 'check.argv');\n  if (argv.length === 0) throw new Error('Comparison check.argv must name the project gate.');\n  return {\n    original_base: string(input.original_base, 'original_base'),\n    base: string(input.base, 'base'),\n    head: string(input.head, 'head'),\n    change: string(input.change, 'change'),\n    base_changes: strings(input.base_changes, 'base_changes'),\n    method: input.method,\n    check: {\n      name: string(check.name, 'check.name'),\n      argv,\n      environment: string(check.environment, 'check.environment'),\n    },\n  };\n}\n\nfunction git(cwd: string, args: string[], env?: Record<string, string | undefined>): string {\n  const result = Bun.spawnSync(['git', ...args], { cwd, env, stdout: 'pipe', stderr: 'pipe' });\n  if (result.exitCode !== 0) {\n    // Only local object/worktree commands reach this helper; no credential-bearing remote is used.\n    throw new Error(\n      `Local git ${args[0]} failed (exit ${result.exitCode}): ${result.stderr.toString().trim()}`\n    );\n  }\n  return result.stdout.toString().trim();\n}\n\nfunction revision(cwd: string, id: string): Revision {\n  if (!/^[a-f0-9]+$/.test(id)) throw new Error('Comparison revisions must be full Git object IDs.');\n  const commit = git(cwd, ['rev-parse', '--verify', `${id}^{commit}`]);\n  if (commit !== id)\n    throw new Error('Comparison revisions must be full commit IDs, not abbreviations.');\n  return { commit, tree: git(cwd, ['rev-parse', `${commit}^{tree}`]) };\n}\n\nfunction digest(value: unknown): string {\n  return createHash('sha256').update(JSON.stringify(value)).digest('hex');\n}\n\n/** A caller supplies current authoritative facts; this never resolves a moving branch for it. */\nexport function evidenceMatches(\n  evidence: CompositionEvidence,\n  current: { repository: string; request: CompositionRequest; candidate: Revision }\n): boolean {\n  return (\n    evidence.repository === current.repository &&\n    digest(evidence.request) === digest(current.request) &&\n    evidence.candidate?.commit === current.candidate.commit &&\n    evidence.candidate.tree === current.candidate.tree\n  );\n}\n\nfunction passed(observation: Observation): boolean {\n  return (\n    observation.exit_code === 0 &&\n    observation.git_clean_after &&\n    observation.head_after === observation.subject.commit\n  );\n}\n\nexport function comparisonVerdict(\n  evidence: CompositionEvidence,\n  evidencePath: string\n): ValidationVerdict {\n  const composed = evidence.observations.find(item => item.subject.role === 'composition');\n  const change = evidence.observations.find(item => item.subject.role === 'change-alone');\n  const base = evidence.observations.find(item => item.subject.role === 'base-alone');\n  const identity = `${evidence.request.change} (${evidence.head.commit}) onto ${evidence.request.base_changes.join(', ') || 'the incoming base'} (${evidence.base.commit})`;\n  if (!composed) {\n    return {\n      green: false,\n      red_cause: '',\n      summary: `No composed gate ran for ${identity}: ${evidence.composition?.exit_code === 1 ? 'local composition conflicted' : 'composition evidence is incomplete'}. Evidence: ${evidencePath}.`,\n    };\n  }\n  const valid =\n    evidence.observations.length === 3 &&\n    change &&\n    base &&\n    change.subject.commit === evidence.head.commit &&\n    change.subject.tree === evidence.head.tree &&\n    base.subject.commit === evidence.base.commit &&\n    base.subject.tree === evidence.base.tree &&\n    composed.subject.commit === evidence.candidate?.commit &&\n    composed.subject.tree === evidence.candidate.tree &&\n    evidence.observations.every(\n      item =>\n        item.git_clean_after &&\n        item.head_after === item.subject.commit &&\n        item.check_digest === digest(evidence.request.check) &&\n        digest(item.command) === item.check_digest\n    );\n  if (!valid) {\n    return {\n      green: false,\n      red_cause: '',\n      summary: `Comparison evidence is incomplete, mismatched, or the gate changed a checkout. No clean-tree verdict for ${identity}. Evidence: ${evidencePath}.`,\n    };\n  }\n  if (passed(composed)) {\n    return {\n      green: true,\n      red_cause: '',\n      summary: `${evidence.request.check.name} passed on composed tree ${composed.subject.tree} for ${identity}. Evidence: ${evidencePath}.`,\n    };\n  }\n  const interaction = passed(change) && passed(base);\n  const diagnostic = readFileSync(composed.log, 'utf8').trim().slice(-2000);\n  return {\n    green: false,\n    red_cause: interaction ? 'interaction' : 'introduced',\n    summary: `${evidence.request.check.name} failed on composed tree ${composed.subject.tree} for ${identity}. ${interaction ? 'Both separate trees passed the same gate; this proves an interaction with the recorded incoming base/prefix, not a pair inferred from file overlap.' : 'Separate green evidence is absent; the cause remains introduced.'} Failing output: ${composed.log}. Evidence: ${evidencePath}.${diagnostic ? `\\nGate diagnostic (tail):\\n${diagnostic}` : ''}`,\n  };\n}\n\n/** Execute one authored project command in three clean, pinned worktrees. No remote writes. */\nexport async function compareComposition(\n  cwd: string,\n  artifacts: string,\n  request: CompositionRequest\n): Promise<{ verdict: ValidationVerdict; evidence: CompositionEvidence; path: string }> {\n  const original = revision(cwd, request.original_base);\n  const base = revision(cwd, request.base);\n  const head = revision(cwd, request.head);\n  const ancestor = Bun.spawnSync(\n    ['git', 'merge-base', '--is-ancestor', original.commit, head.commit],\n    { cwd }\n  );\n  if (ancestor.exitCode !== 0)\n    throw new Error('Original comparison base must be an ancestor of the pinned head.');\n  mkdirSync(artifacts, { recursive: true });\n  const directory = mkdtempSync(join(artifacts, 'comparison-'));\n  const path = join(directory, 'evidence.json');\n  const evidence: CompositionEvidence = {\n    version: 1,\n    repository: resolve(cwd, git(cwd, ['rev-parse', '--git-common-dir'])),\n    request,\n    original_base: original,\n    base,\n    head,\n    merge_bases: null,\n    candidate: null,\n    runtime: { platform: platform(), arch: arch(), bun: Bun.version, git: git(cwd, ['--version']) },\n    observations: [],\n    composition: null,\n  };\n  const composed = Bun.spawnSync(['git', 'merge-tree', '--write-tree', base.commit, head.commit], {\n    cwd,\n    stdout: 'pipe',\n    stderr: 'pipe',\n  });\n  evidence.composition = {\n    exit_code: composed.exitCode,\n    stdout: join(directory, 'composition.stdout.log'),\n    stderr: join(directory, 'composition.stderr.log'),\n  };\n  writeFileSync(evidence.composition.stdout, composed.stdout);\n  writeFileSync(evidence.composition.stderr, composed.stderr);\n  writeFileSync(path, JSON.stringify(evidence, null, 2));\n  if (composed.exitCode !== 0 && composed.exitCode !== 1) {\n    throw new Error(\n      `Local composition failed (exit ${composed.exitCode}). Evidence: ${path}.\\n${composed.stdout.toString()}${composed.stderr.toString()}`\n    );\n  }\n  evidence.merge_bases = git(cwd, ['merge-base', '--all', base.commit, head.commit]).split('\\n');\n  if (composed.exitCode === 0) {\n    const tree = composed.stdout.toString().trim().split('\\n')[0];\n    if (!tree || !/^[a-f0-9]+$/.test(tree))\n      throw new Error('Local composition did not return a tree ID.');\n    const parents =\n      request.method === 'merge' ? ['-p', base.commit, '-p', head.commit] : ['-p', base.commit];\n    const candidate = git(\n      cwd,\n      [\n        '-c',\n        'commit.gpgSign=false',\n        'commit-tree',\n        tree,\n        ...parents,\n        '-m',\n        'Archon composition validation',\n      ],\n      {\n        ...process.env,\n        GIT_AUTHOR_NAME: 'Archon validation',\n        GIT_AUTHOR_EMAIL: 'validation@localhost',\n        GIT_COMMITTER_NAME: 'Archon validation',\n        GIT_COMMITTER_EMAIL: 'validation@localhost',\n        GIT_AUTHOR_DATE: '2000-01-01T00:00:00Z',\n        GIT_COMMITTER_DATE: '2000-01-01T00:00:00Z',\n      }\n    );\n    evidence.candidate = { commit: candidate, tree };\n    const subjects: Subject[] = [\n      { role: 'change-alone', ...head },\n      { role: 'base-alone', ...base },\n      { role: 'composition', ...evidence.candidate },\n    ];\n    // One frozen process environment for this comparison. The caller's environment label\n    // identifies external dependencies; it is not a claim that databases/network are immutable.\n    // The gate is the project's, not part of this run, so it never sees the node's contract.\n    const env = projectEnvironment(process.env);\n    for (const subject of subjects) {\n      const worktree = join(directory, subject.role);\n      git(cwd, ['worktree', 'add', '--detach', worktree, subject.commit]);\n      try {\n        if (git(worktree, ['status', '--porcelain', '--untracked-files=all']) !== '') {\n          throw new Error('Comparison worktree is not clean before the gate.');\n        }\n        const log = join(directory, `${subject.role}.log`);\n        const fd = openSync(log, 'wx');\n        const started = new Date().toISOString();\n        let exitCode: number;\n        try {\n          const child = Bun.spawn(request.check.argv, {\n            cwd: worktree,\n            env,\n            stdout: fd,\n            stderr: fd,\n            stdin: 'ignore',\n          });\n          exitCode = await child.exited;\n        } finally {\n          closeSync(fd);\n        }\n        evidence.observations.push({\n          subject,\n          command: request.check,\n          check_digest: digest(request.check),\n          exit_code: exitCode,\n          git_clean_after: git(worktree, ['status', '--porcelain', '--untracked-files=all']) === '',\n          head_after: git(worktree, ['rev-parse', 'HEAD']),\n          log,\n          started_at: started,\n          finished_at: new Date().toISOString(),\n        });\n        writeFileSync(path, JSON.stringify(evidence, null, 2));\n      } finally {\n        git(cwd, ['worktree', 'remove', '--force', worktree]);\n      }\n    }\n  }\n  writeFileSync(path, JSON.stringify(evidence, null, 2));\n  const verdict = comparisonVerdict(evidence, path);\n  writeFileSync(join(directory, 'validation.md'), `${verdict.summary}\\n`);\n  return { verdict, evidence, path };\n}\n\nexport function readComparisonRequest(path: string): CompositionRequest {\n  return parseCompositionRequest(JSON.parse(readFileSync(path, 'utf8')) as unknown);\n}\n",".shared/forge.ts":"/**\n * Standalone client for `archon forge`, the pack's opt-in forge source.\n *\n * One switch selects the source for every forge read and write this pack makes:\n *\n *   gh     the default. The GitHub CLI, as the pack has always used it.\n *   forge  opt-in with `ARCHON_SDLC_FORGE=forge`. An installed forge plugin,\n *          reached through the host command (`ARCHON_CLI_COMMAND`) the CLI and\n *          server publish.\n *\n * The source is never inferred from what happens to be installed, and a selected\n * source that cannot answer fails the operation rather than falling back to the\n * other. A container execution receives neither variable, so it uses `gh`.\n */\n\nimport { mkdtempSync, rmSync, writeFileSync } from 'node:fs';\nimport { tmpdir } from 'node:os';\nimport { join } from 'node:path';\nimport { note } from './io.ts';\n\nexport type ForgeSource = 'gh' | 'forge';\n\n// Read here, not in each calling script: the unbound-env checker scans a node-bound\n// script's own text but never follows its imports, so a bare process.env read in a\n// shared module like this one never trips a false \"unbound variable\" warning.\nexport function forgeSource(): ForgeSource {\n  const selected = (process.env.ARCHON_SDLC_FORGE ?? '').trim();\n  if (selected === '' || selected === 'gh') return 'gh';\n  if (selected === 'forge') return 'forge';\n  throw new Error(`ARCHON_SDLC_FORGE must be \"gh\" (the default) or \"forge\", not \"${selected}\"`);\n}\n\nexport interface QualifiedPr {\n  readonly repo: { readonly host: string; readonly path: string };\n  readonly number: number;\n}\n\n/** The pull-request facts every later public action in a run depends on. */\nexport interface PrRecord extends QualifiedPr {\n  readonly schemaVersion: 1;\n  readonly url: string;\n  readonly head: string;\n  readonly base: string;\n  readonly is_draft: boolean;\n  readonly state: 'open' | 'closed' | 'merged';\n  readonly head_repo: { readonly host: string; readonly path: string } | null;\n  readonly head_revision: string | null;\n  readonly base_revision: string | null;\n  readonly maintainer_can_modify: boolean | null;\n}\n\nexport interface MergeRequest {\n  readonly ref: QualifiedPr;\n  readonly method: 'merge' | 'squash';\n  readonly conditions: { readonly head?: string; readonly base?: string; readonly tree?: string };\n}\nexport interface Landed {\n  readonly commit: string | null;\n  readonly tree: string | null;\n  readonly parents: readonly string[] | null;\n}\nexport interface MergeResult extends Omit<MergeRequest, 'ref'> {\n  readonly target: QualifiedPr;\n  readonly outcome: 'applied';\n  readonly changed: true;\n  readonly pr: PrRecord;\n  readonly enforcedConditions: readonly (keyof MergeRequest['conditions'])[];\n  readonly landed: Landed;\n}\nexport interface ReviewItem {\n  readonly kind: 'review' | 'review_comment';\n  readonly id: string;\n  readonly author: {\n    readonly host: string;\n    readonly id: string;\n    readonly login: string | null;\n  } | null;\n  readonly commit: string | null;\n  readonly state: string | null;\n  readonly createdAt: string | null;\n  readonly url: string;\n  readonly body: string;\n}\nexport interface ReviewsResult {\n  readonly ref: QualifiedPr;\n  readonly items: readonly ReviewItem[];\n}\nexport interface MutationFailure {\n  readonly op: string;\n  readonly target: QualifiedPr | QualifiedPr['repo'];\n  readonly outcome: 'refused' | 'verification_failed' | 'outcome_unknown';\n  readonly leaveBehind?: string;\n  readonly observed?: PrRecord;\n  readonly merge?: {\n    readonly method: MergeRequest['method'];\n    readonly conditions: MergeRequest['conditions'];\n    readonly landed?: Landed;\n  };\n}\n\n/**\n * Repository identity, compared the way a forge registers it.\n *\n * Host and owner/name are case-insensitive but case-preserving: a forge answers\n * with the case it has registered, whatever case this pack asked with. Comparing\n * exactly would read a pull request that is the requested one as a different one.\n */\nexport function sameRepo(left: QualifiedPr['repo'], right: QualifiedPr['repo']): boolean {\n  return (\n    left.host.toLowerCase() === right.host.toLowerCase() &&\n    left.path.toLowerCase() === right.path.toLowerCase()\n  );\n}\n\nexport function record(value: unknown): Record<string, unknown> | undefined {\n  return typeof value === 'object' && value !== null\n    ? (value as Record<string, unknown>)\n    : undefined;\n}\n\n/**\n * A forge operation that did not produce a verified result.\n *\n * `mutation` carries the evidence a write owes its caller: which of `refused`,\n * `verification_failed` or `outcome_unknown` happened, and what may remain on the\n * forge. A caller may report it; it may never retry past an unknown outcome.\n */\nexport class ForgeOperationError extends Error {\n  constructor(\n    message: string,\n    readonly mutation: Record<string, unknown> | undefined\n  ) {\n    super(message);\n    this.name = 'ForgeOperationError';\n  }\n}\n\n/**\n * Run one typed forge operation.\n *\n * The request travels as a file so authored content — a pull-request body, a\n * review report — never appears in any process's argv.\n */\nexport function invokeForge(\n  op: string,\n  request: Record<string, unknown>\n): Record<string, unknown> | null {\n  const command = archonCommand();\n  const directory = mkdtempSync(join(tmpdir(), 'archon-forge-'));\n  const path = join(directory, 'request.json');\n  try {\n    writeFileSync(path, JSON.stringify(request), { mode: 0o600 });\n    const result = Bun.spawnSync([...command, 'forge', op, '--json', '--data-file', path], {\n      stdout: 'pipe',\n      stderr: 'pipe',\n    });\n    let parsed: unknown;\n    try {\n      parsed = JSON.parse(result.stdout.toString());\n    } catch {\n      const detail = result.stderr.toString().trim();\n      throw new Error(`forge ${op} failed${detail === '' ? '' : `: ${detail}`}`);\n    }\n    const response = record(parsed);\n    if (!response || typeof response.operationId !== 'string' || response.operationId === '') {\n      throw new Error(`forge ${op} returned an unexpected response envelope`);\n    }\n    // Exit 2 is the host saying it could not audit an operation that did complete.\n    // The response on stdout is the real outcome, so the result is still a result;\n    // losing it here would report a performed write as a failure.\n    if (response.ok === true && result.exitCode === 2) {\n      note(`forge ${op} completed but the host could not record it in the run's audit log.`);\n    } else if (response.ok !== true || result.exitCode !== 0) {\n      const mutation = record(response.mutation);\n      const error = record(response.error);\n      const outcome = typeof mutation?.outcome === 'string' ? mutation.outcome : undefined;\n      const message = typeof error?.message === 'string' ? error.message : 'operation failed';\n      throw new ForgeOperationError(\n        `forge ${op} ${outcome ?? 'failed'}: ${message}${mutation ? ` ${JSON.stringify(mutation)}` : ''}`,\n        mutation\n      );\n    }\n    const body = record(response.result);\n    if (body?.op !== op) throw new Error(`forge ${op} returned the wrong result`);\n    // A read may answer \"there is none\": `pr.view` by head returns null when the\n    // branch has no open pull request.\n    if (body.value === null) return null;\n    const value = record(body.value);\n    if (!value) throw new Error(`forge ${op} returned the wrong result`);\n    return value;\n  } finally {\n    rmSync(directory, { recursive: true, force: true });\n  }\n}\n\nfunction qualifiedRepo(value: unknown): QualifiedPr['repo'] | undefined {\n  const repo = record(value);\n  return typeof repo?.host === 'string' &&\n    repo.host.trim() !== '' &&\n    typeof repo.path === 'string' &&\n    repo.path.trim() !== ''\n    ? { host: repo.host, path: repo.path }\n    : undefined;\n}\n\n/** Validate only the pull-request facts this pack's policy consumes. */\nexport function parsePrRecord(value: unknown): PrRecord {\n  const pr = record(value);\n  const repo = qualifiedRepo(pr?.repo);\n  const headRepo = pr?.head_repo === null ? null : qualifiedRepo(pr?.head_repo);\n  const optionalText = (field: unknown): boolean =>\n    field === null || (typeof field === 'string' && field !== '');\n  if (\n    pr?.schemaVersion !== 1 ||\n    !repo ||\n    typeof pr.number !== 'number' ||\n    !Number.isInteger(pr.number) ||\n    pr.number <= 0 ||\n    typeof pr.url !== 'string' ||\n    !URL.canParse(pr.url) ||\n    typeof pr.head !== 'string' ||\n    pr.head === '' ||\n    typeof pr.base !== 'string' ||\n    pr.base === '' ||\n    typeof pr.is_draft !== 'boolean' ||\n    (pr.state !== 'open' && pr.state !== 'closed' && pr.state !== 'merged') ||\n    headRepo === undefined ||\n    !optionalText(pr.head_revision) ||\n    !optionalText(pr.base_revision) ||\n    !(typeof pr.maintainer_can_modify === 'boolean' || pr.maintainer_can_modify === null)\n  ) {\n    throw new Error('forge returned an invalid pull-request record');\n  }\n  return {\n    schemaVersion: 1,\n    repo,\n    number: pr.number,\n    url: pr.url,\n    head: pr.head,\n    base: pr.base,\n    is_draft: pr.is_draft,\n    state: pr.state,\n    head_repo: headRepo,\n    head_revision: pr.head_revision as string | null,\n    base_revision: pr.base_revision as string | null,\n    maintainer_can_modify: pr.maintainer_can_modify,\n  };\n}\n\nexport function parseQualifiedPr(value: string | undefined): QualifiedPr {\n  let parsed: unknown;\n  try {\n    parsed = JSON.parse(value ?? '');\n  } catch {\n    throw new Error('the bound pull request is not valid JSON');\n  }\n  const pr = record(parsed);\n  const repo = record(pr?.repo);\n  if (\n    typeof repo?.host !== 'string' ||\n    repo.host.trim() === '' ||\n    typeof repo.path !== 'string' ||\n    repo.path.trim() === '' ||\n    typeof pr?.number !== 'number' ||\n    !Number.isInteger(pr.number) ||\n    pr.number <= 0\n  ) {\n    throw new Error('the bound pull request has no qualified repo and positive number');\n  }\n  return { repo: { host: repo.host, path: repo.path }, number: pr.number };\n}\n\n/** The host's `archon` argv, as the CLI and server publish it to every exec node. */\nexport function archonCommand(): readonly string[] {\n  const value = process.env.ARCHON_CLI_COMMAND;\n  if (value === undefined || value === '') {\n    throw new Error(\n      'ARCHON_CLI_COMMAND is not set; the host that started this run did not publish its CLI command'\n    );\n  }\n  let parsed: unknown;\n  try {\n    parsed = JSON.parse(value);\n  } catch {\n    throw new Error('ARCHON_CLI_COMMAND is not a JSON string array');\n  }\n  if (\n    !Array.isArray(parsed) ||\n    parsed.length === 0 ||\n    !parsed.every(part => typeof part === 'string' && part !== '')\n  ) {\n    throw new Error('ARCHON_CLI_COMMAND must be a non-empty JSON string array');\n  }\n  return parsed as string[];\n}\n\nexport function samePr(left: QualifiedPr, right: QualifiedPr): boolean {\n  return left.number === right.number && sameRepo(left.repo, right.repo);\n}\n\nexport function readRepositoryLabels(repo: QualifiedPr['repo']): string[] {\n  const value = invokeForge('repo.labels.list', { repo });\n  const observed = qualifiedRepo(value?.repo);\n  if (!observed || !sameRepo(repo, observed) || !Array.isArray(value?.labels))\n    throw new Error('forge returned invalid repository labels');\n  return value.labels.map(row => {\n    const label = record(row);\n    if (typeof label?.name !== 'string' || label.name === '')\n      throw new Error('forge returned invalid repository label');\n    return label.name;\n  });\n}\n",".shared/git.ts":"/** One git call, captured: a node's stderr reaches the operator, so only this pack's messages may. */\nexport interface GitResult {\n  readonly code: number;\n  readonly stdout: string;\n  readonly stderr: string;\n}\n\nexport function git(...args: string[]): GitResult {\n  const result = Bun.spawnSync(['git', ...args], { stdout: 'pipe', stderr: 'pipe' });\n  return {\n    code: result.exitCode,\n    stdout: result.stdout.toString().trim(),\n    stderr: result.stderr.toString().trim(),\n  };\n}\n\n/** A git call whose failure is a broken assumption: its stdout, or a throw naming the command. */\nexport function gitOrThrow(...args: string[]): string {\n  const result = git(...args);\n  if (result.code !== 0) throw new Error(`git ${args.join(' ')} failed: ${result.stderr}`);\n  return result.stdout;\n}\n",".shared/io.ts":"/**\n * The process contract every deterministic script in this pack shares.\n *\n * A node's `with:` bindings arrive as `INPUTS_<UPPER_SNAKE>` environment text and\n * are always strings: a bound boolean arrives as `\"true\"`/`\"false\"`, a skipped\n * producer bound with `if_skipped: null` arrives as `\"null\"`, and a field its\n * producer declared null arrives as empty text. `nullableJson` reads the last two\n * alike; beyond that nothing here interprets those spellings — what a value means\n * belongs to the script that knows what it is for.\n *\n * Read every binding as a literal `process.env.INPUTS_<NAME>` at its own call site\n * and pass the value in. The engine scans each script's source at workflow load and\n * refuses a workflow whose script reads a binding no `with:` clause or declared\n * input provides. It matches the literal form only, and it reads the entry script\n * alone, never its imports — so a helper that composed the key from a name would\n * hide every read in this pack from that check.\n *\n * Bun writes UTF-8 with `\\n` line endings on every platform, so a terminal report\n * composed here is byte-identical wherever a run happens. Nothing in this pack needs\n * to pin either by hand.\n */\n\n/**\n * Never call `process.exit()` in a packaged script.\n *\n * Bun 1.4.2 exits without draining stdout: a 500 KB write to a pipe arrives as\n * exactly 131072 bytes, silently. A truncated terminal report reads as a complete\n * one, and a truncated JSON document fails its node's certification with a message\n * about the schema rather than about the truncation. Setting `process.exitCode` and\n * returning lets the runtime flush before it leaves, which is why every helper here\n * sets the code instead of forcing the exit.\n */\nfunction setFailed(): void {\n  process.exitCode = 1;\n}\n\n/** A bound input's value, or the empty string when the binding is absent. */\nexport function text(value: string | undefined): string {\n  return value ?? '';\n}\n\n/** A bound input's value with surrounding whitespace removed. */\nexport function trimmed(value: string | undefined): string {\n  return (value ?? '').trim();\n}\n\n/**\n * A bound JSON value that may be null. The engine binds a field the producer declared\n * null as empty text, and a literal or `if_skipped` null as `null`; both read as null.\n */\nexport function nullableJson(value: string | undefined): unknown {\n  const raw = trimmed(value);\n  return raw === '' ? null : (JSON.parse(raw) as unknown);\n}\n\n/**\n * This run's artifact directory.\n *\n * The engine supplies it to every exec node, so its absence is a bug in the engine\n * or in the node's declaration rather than a state a script should report on. This\n * throws instead of substituting a default that would read or write somewhere else.\n */\nexport function artifactsDir(): string {\n  const value = process.env.ARTIFACTS_DIR;\n  if (value === undefined || value === '') {\n    throw new Error('ARTIFACTS_DIR is not set; the engine supplies it to every exec node.');\n  }\n  return value;\n}\n\n/**\n * The node's result: one strict JSON document on stdout.\n *\n * A node that declares `output_format` gets exactly one attempt — no fence\n * stripping, no repair pass, no reask — so this is the only way a certified script\n * writes its result.\n */\nexport function emit(value: unknown): void {\n  console.log(JSON.stringify(value));\n}\n\n/** A plain-text result, for a node that declares no schema. */\nexport function report(value: string): void {\n  console.log(value);\n}\n\n/**\n * The node's refusal: the reason on stderr, a non-zero exit, nothing on stdout.\n *\n * The engine broadcasts stderr to the operator as the run happens and retains it on\n * the `node_failed` event, so the message is the whole diagnostic.\n */\nexport function refuse(message: string): void {\n  console.error(message);\n  setFailed();\n}\n\n/**\n * A note the operator should see from a node that is not failing.\n *\n * Stderr reaches the operator even on the success path, which is what keeps a gate\n * that deliberately passed red loud rather than silent.\n */\nexport function note(message: string): void {\n  console.error(message);\n}\n",".shared/issue.ts":"/**\n * The pack's one issue read, through whichever source the run selected (./forge.ts).\n *\n * Both sources prove the number names an issue on the tracker before anything is\n * returned, so a pull request with the same number is never read as the issue.\n * `issueAtCreation` recovers the text an issue was opened with, from GitHub's edit\n * history; the forge source has no history and answers with the current text.\n */\n\nimport {\n  forgeSource,\n  invokeForge,\n  parseQualifiedPr,\n  record,\n  samePr,\n  type QualifiedPr,\n} from './forge.ts';\n\nexport interface IssueView {\n  readonly title: string;\n  readonly body: string;\n  /**\n   * The author's login. Null when the forge has none (a deleted account);\n   * undefined when the source does not report an author at all.\n   */\n  readonly author: string | null | undefined;\n  readonly labels: readonly string[];\n  readonly state: 'open' | 'closed';\n  readonly url: string;\n}\n\nexport function viewIssue(item: QualifiedPr): IssueView {\n  return forgeSource() === 'forge' ? forgeView(item) : ghView(item);\n}\n\nfunction labelNames(values: unknown[]): string[] {\n  return values.map(value => {\n    const name = typeof value === 'string' ? value : record(value)?.name;\n    if (typeof name !== 'string' || name === '') throw new Error('the issue has an invalid label');\n    return name;\n  });\n}\n\nfunction login(value: unknown): string | null {\n  return typeof value === 'string' && value !== '' ? value : null;\n}\n\nfunction ghView(item: QualifiedPr): IssueView {\n  const result = Bun.spawnSync(\n    [\n      'gh',\n      'api',\n      '--hostname',\n      item.repo.host,\n      `repos/${item.repo.path}/issues/${String(item.number)}`,\n    ],\n    { stdout: 'pipe', stderr: 'pipe' }\n  );\n  if (result.exitCode !== 0) {\n    throw new Error(\n      `gh api issues/${String(item.number)} failed: ${result.stderr.toString().trim()}`\n    );\n  }\n  const issue = record(JSON.parse(result.stdout.toString()));\n  const url = `https://${item.repo.host}/${item.repo.path}/issues/${String(item.number)}`;\n  if (\n    issue?.number !== item.number ||\n    (typeof issue.html_url === 'string' ? issue.html_url : '').toLowerCase() !==\n      url.toLowerCase() ||\n    'pull_request' in issue\n  ) {\n    throw new Error(`tracker identity mismatch: ${url} does not answer as that issue`);\n  }\n  if (issue.state !== 'open' && issue.state !== 'closed') {\n    throw new Error(`${url} has no open or closed state`);\n  }\n  return {\n    title: typeof issue.title === 'string' ? issue.title : '',\n    body: typeof issue.body === 'string' ? issue.body : '',\n    author: login(record(issue.user)?.login),\n    labels: labelNames(Array.isArray(issue.labels) ? issue.labels : []),\n    state: issue.state,\n    url: issue.html_url as string,\n  };\n}\n\nfunction forgeView(item: QualifiedPr): IssueView {\n  const value = invokeForge('workitem.view', { ref: item });\n  const observed = parseQualifiedPr(JSON.stringify(value?.ref));\n  if (\n    !samePr(item, observed) ||\n    value?.kind !== 'issue' ||\n    !Array.isArray(value.labels) ||\n    typeof value.title !== 'string' ||\n    typeof value.body !== 'string' ||\n    typeof value.url !== 'string' ||\n    (value.state !== 'open' && value.state !== 'closed')\n  ) {\n    throw new Error('forge work item has no verified issue identity and label facts');\n  }\n  return {\n    title: value.title,\n    body: value.body,\n    // Absent: the plugin does not report an author. Null: the forge has none.\n    author: value.author === undefined ? undefined : login(record(value.author)?.login),\n    labels: labelNames(value.labels),\n    state: value.state,\n    url: value.url,\n  };\n}\n\n/** `current` when the creation body could not be recovered and the current one stands in. */\nexport const BODY_SOURCES = ['creation', 'current'] as const;\n\n/** The title and body an issue was opened with, and whether the body really is that. */\nexport interface IssueAtCreation {\n  readonly title: string;\n  readonly body: string;\n  readonly body_from: (typeof BODY_SOURCES)[number];\n}\n\nconst CREATION_QUERY = [\n  'query($owner: String!, $name: String!, $number: Int!) {',\n  'repository(owner: $owner, name: $name) { issue(number: $number) {',\n  'createdAt',\n  'userContentEdits(last: 1) { totalCount nodes { editedAt diff } }',\n  'timelineItems(first: 1, itemTypes: [RENAMED_TITLE_EVENT]) {',\n  'nodes { ... on RenamedTitleEvent { previousTitle } } }',\n  '} } }',\n].join(' ');\n\nexport function issueAtCreation(item: QualifiedPr, current: IssueView): IssueAtCreation {\n  if (forgeSource() === 'forge') {\n    return { title: current.title, body: current.body, body_from: 'current' };\n  }\n  const slash = item.repo.path.indexOf('/');\n  const result = Bun.spawnSync(\n    [\n      'gh',\n      'api',\n      'graphql',\n      '--hostname',\n      item.repo.host,\n      '-f',\n      `query=${CREATION_QUERY}`,\n      '-f',\n      `owner=${item.repo.path.slice(0, slash)}`,\n      '-f',\n      `name=${item.repo.path.slice(slash + 1)}`,\n      '-F',\n      `number=${String(item.number)}`,\n    ],\n    { stdout: 'pipe', stderr: 'pipe' }\n  );\n  if (result.exitCode !== 0) {\n    throw new Error(\n      `gh api graphql (issue ${String(item.number)} history) failed: ${result.stderr.toString().trim()}`\n    );\n  }\n  const data = record(record(JSON.parse(result.stdout.toString()))?.data);\n  const history = record(record(data?.repository)?.issue);\n  const edits = record(history?.userContentEdits);\n  if (history === undefined || typeof edits?.totalCount !== 'number') {\n    throw new Error(`issue ${String(item.number)} has no edit history to read`);\n  }\n  // Edits are newest first and each holds the whole body at that revision, so the\n  // last one is the oldest. It is the creation body when it was made at creation; a\n  // deleted revision has no diff, and then the current body stands in, visibly.\n  const oldest = record(Array.isArray(edits.nodes) ? edits.nodes[0] : undefined);\n  const recovered =\n    edits.totalCount === 0\n      ? current.body\n      : typeof oldest?.diff === 'string' && oldest.editedAt === history.createdAt\n        ? oldest.diff\n        : undefined;\n  const renames = record(history.timelineItems)?.nodes;\n  const previousTitle = record(Array.isArray(renames) ? renames[0] : undefined)?.previousTitle;\n  return {\n    title: typeof previousTitle === 'string' ? previousTitle : current.title,\n    body: recovered ?? current.body,\n    body_from: recovered === undefined ? 'current' : 'creation',\n  };\n}\n",".shared/labels.ts":"/**\n * The pack's labels and the one write that applies them.\n *\n * Every label the pack writes is declared here with its color and description,\n * and every stage that writes labels goes through `writeLabels`. Stages are\n * joined by labels, one stage's exit label being the next stage's entry label,\n * so a name declared anywhere else is a copy that can drift.\n */\n\nimport { forgeSource, invokeForge, readRepositoryLabels, type QualifiedPr } from './forge.ts';\nimport { viewIssue } from './issue.ts';\n\ninterface LabelSpec {\n  readonly color: string;\n  readonly description: string;\n}\n\nexport const PACK_LABELS = {\n  'archon-ready': { color: '0E8A16', description: 'Triage: ready to deliver' },\n  'archon-plan': { color: '1D76DB', description: 'Triage: ready; a plan comes before delivery' },\n  'archon-issue': {\n    color: 'C5DEF5',\n    description: 'Triage: ready; an investigation comes before delivery',\n  },\n  'archon-needs-contract': {\n    color: 'D93F0B',\n    description: \"Triage: one of the contract's six elements is missing\",\n  },\n  'archon-blocked': {\n    color: 'B60205',\n    description: 'Triage: a prerequisite or human decision must land first',\n  },\n  'archon-close': {\n    color: '6A737D',\n    description: 'Triage: already delivered, duplicate, obsolete, or out of direction',\n  },\n  'archon-type-bug': { color: 'D73A4A', description: 'Triage: something that worked is broken' },\n  'archon-type-feature': { color: 'A2EEEF', description: 'Triage: new behavior' },\n  'archon-type-refactor': { color: 'BFD4F2', description: 'Triage: same behavior, better structure' },\n  'archon-type-maintenance': {\n    color: 'D4C5F9',\n    description: 'Triage: dependencies, tooling, CI, or upkeep',\n  },\n  'archon-type-docs': { color: '0075CA', description: 'Triage: documentation only' },\n  'archon-type-question': { color: 'D876E3', description: 'Triage: a question for a person' },\n  'archon-size-s': { color: 'C2E0C6', description: 'Triage: a few files on one surface' },\n  'archon-size-m': { color: 'FEF2C0', description: 'Triage: several files or two surfaces' },\n  'archon-size-l': { color: 'F9D0C4', description: 'Triage: several packages, schemas, or surfaces' },\n  'archon-needs-maintainer': {\n    color: 'FBCA04',\n    description: 'Intake: an outside item waits for a maintainer to promote it',\n  },\n  'archon-triage': {\n    color: '5319E7',\n    description: 'Intake: a request to triage this item; intake removes it when done',\n  },\n} as const satisfies Record<string, LabelSpec>;\n\nexport type PackLabel = keyof typeof PACK_LABELS;\n\nexport function isPackLabel(name: string): name is PackLabel {\n  return Object.hasOwn(PACK_LABELS, name);\n}\n\n// Labels an earlier version of the pack wrote. A write removes them from the item\n// and never creates them, so re-triaging an item clears its old size label.\nconst RETIRED_LABELS = ['archon-small', 'archon-risky', 'archon-large'] as const;\n\n/** A label the pack owns on an item: one it writes now, or one it retired. */\nexport type OwnedLabel = PackLabel | (typeof RETIRED_LABELS)[number];\n\nexport const OWNED_LABEL_NAMES: readonly OwnedLabel[] = [\n  ...(Object.keys(PACK_LABELS) as PackLabel[]),\n  ...RETIRED_LABELS,\n];\n\nexport function isOwnedLabel(name: string): name is OwnedLabel {\n  return (OWNED_LABEL_NAMES as readonly string[]).includes(name);\n}\n\nexport type Contract = 'READY' | 'NEEDS_CONTRACT_WORK' | 'BLOCKED' | 'NO_ACTION';\nexport type WorkType = 'bug' | 'feature' | 'refactor' | 'maintenance' | 'docs' | 'question';\nexport type Size = 's' | 'm' | 'l';\nexport type Route = 'investigate' | 'plan' | 'deliver' | 'continue';\n\n// Exactly one state label per item. A READY item's label names the route the run\n// takes on it: archon-ready delivers (a new pull request, or the open one it\n// continues), archon-plan plans then delivers, and archon-issue investigates then\n// delivers.\nexport const STATE_LABEL = {\n  NEEDS_CONTRACT_WORK: 'archon-needs-contract',\n  BLOCKED: 'archon-blocked',\n  NO_ACTION: 'archon-close',\n} as const satisfies Record<Exclude<Contract, 'READY'>, PackLabel>;\nexport const ROUTE_LABEL = {\n  deliver: 'archon-ready',\n  continue: 'archon-ready',\n  plan: 'archon-plan',\n  investigate: 'archon-issue',\n} as const satisfies Record<Route, PackLabel>;\n// Of triage's five fields only type and size become labels, the two a person\n// filters by; complexity, importance and urgency stay in the verdict.\nexport const TYPE_LABEL = {\n  bug: 'archon-type-bug',\n  feature: 'archon-type-feature',\n  refactor: 'archon-type-refactor',\n  maintenance: 'archon-type-maintenance',\n  docs: 'archon-type-docs',\n  question: 'archon-type-question',\n} as const satisfies Record<WorkType, PackLabel>;\nexport const SIZE_LABEL = {\n  s: 'archon-size-s',\n  m: 'archon-size-m',\n  l: 'archon-size-l',\n} as const satisfies Record<Size, PackLabel>;\n\n/**\n * The labels a person adds to ask intake for something: `archon-triage` asks for\n * triage, and a route label on an outside item promotes it. The pack's own write of\n * a route label is not a request; intake recognizes it as the work item's mirror.\n */\nexport const REQUEST_LABELS: readonly PackLabel[] = [\n  'archon-triage',\n  ...new Set(Object.values(ROUTE_LABEL)),\n];\n\nexport function isRequestLabel(name: string): boolean {\n  return (REQUEST_LABELS as readonly string[]).includes(name);\n}\n\n/** A triage verdict as far as labels read it: a READY item carries its route. */\nexport type LabelVerdict =\n  | { readonly contract: 'READY'; readonly route: Route }\n  | { readonly contract: Exclude<Contract, 'READY'> };\n\n/**\n * The pack labels a verdict derives: one state label and one type label, plus a\n * size label while the item can still be worked; a close verdict carries none.\n */\nexport function wantedLabels(verdict: LabelVerdict, type: WorkType, size: Size): PackLabel[] {\n  const wanted: PackLabel[] = [\n    verdict.contract === 'READY' ? ROUTE_LABEL[verdict.route] : STATE_LABEL[verdict.contract],\n    TYPE_LABEL[type],\n  ];\n  if (verdict.contract !== 'NO_ACTION') wanted.push(SIZE_LABEL[size]);\n  return wanted;\n}\n\nfunction gh(...args: string[]): string {\n  const result = Bun.spawnSync(['gh', ...args], { stdout: 'pipe', stderr: 'pipe' });\n  if (result.exitCode !== 0) {\n    throw new Error(`gh ${args.slice(0, 3).join(' ')} failed: ${result.stderr.toString().trim()}`);\n  }\n  return result.stdout.toString();\n}\n\nfunction ghRepositoryLabels(repository: string): Set<string> {\n  const rows = JSON.parse(\n    gh('label', 'list', '--repo', repository, '--limit', '500', '--json', 'name')\n  ) as { name: string }[];\n  return new Set(rows.map(row => row.name));\n}\n\n/**\n * Add and remove labels on an issue as a delta, then read the result back.\n *\n * The issue's identity is verified before anything is written. A missing pack\n * label is created with its declared color and description; any other label is\n * added only when the repository already has it, because the pack never creates\n * a label it does not own. Returns the added labels now on the issue, sorted.\n */\nexport function writeLabels(\n  item: QualifiedPr,\n  add: readonly string[],\n  remove: readonly OwnedLabel[]\n): string[] {\n  return forgeSource() === 'forge' ? forgeWrite(item, add, remove) : ghWrite(item, add, remove);\n}\n\nfunction ghWrite(item: QualifiedPr, add: readonly string[], remove: readonly OwnedLabel[]): string[] {\n  const repository = `${item.repo.host}/${item.repo.path}`;\n  const current = new Set(viewIssue(item).labels);\n  const present = ghRepositoryLabels(repository);\n  for (const name of add) {\n    if (!present.has(name) && isPackLabel(name)) {\n      const { color, description } = PACK_LABELS[name];\n      gh('label', 'create', name, '--repo', repository, '--color', color, '--description', description);\n      present.add(name);\n    }\n  }\n  const applied = [...new Set(add.filter(name => present.has(name)))].sort();\n  const toAdd = applied.filter(name => !current.has(name));\n  const removing = new Set<string>(remove);\n  const stale = [...current].filter(name => removing.has(name)).sort();\n  // Single add and remove operations, never a whole-set write, so labels another\n  // writer adds concurrently survive.\n  if (toAdd.length > 0 || stale.length > 0) {\n    const args = ['issue', 'edit', String(item.number), '--repo', repository];\n    for (const name of toAdd) args.push('--add-label', name);\n    for (const name of stale) args.push('--remove-label', name);\n    gh(...args);\n  }\n  const after = new Set(viewIssue(item).labels);\n  const missing = applied.filter(name => !after.has(name));\n  const lingering = stale.filter(name => after.has(name));\n  if (missing.length > 0 || lingering.length > 0) {\n    throw new Error(\n      `label read-back disagrees: missing=${JSON.stringify(missing)} lingering=${JSON.stringify(lingering)}`\n    );\n  }\n  return applied;\n}\n\n// The forge seam has no single-label add or remove yet, so this reads the item's\n// labels and writes the whole set back. A label another writer adds between that\n// read and the write is dropped. The race closes when the seam can apply a delta;\n// this path then takes the same single add and remove as the gh path.\nfunction forgeWrite(\n  item: QualifiedPr,\n  add: readonly string[],\n  remove: readonly OwnedLabel[]\n): string[] {\n  const current = viewIssue(item).labels;\n  const present = new Set(readRepositoryLabels(item.repo));\n  for (const name of add) {\n    if (!present.has(name) && isPackLabel(name)) {\n      invokeForge('repo.label.ensure', { repo: item.repo, name, ...PACK_LABELS[name] });\n      present.add(name);\n    }\n  }\n  const applied = [...new Set(add.filter(name => present.has(name)))].sort();\n  const removing = new Set<string>(remove);\n  const labels = [...new Set([...current.filter(name => !removing.has(name)), ...applied])].sort();\n  const result = invokeForge('workitem.labels.set', { ref: item, labels });\n  const observedLabels = result?.labels;\n  if (\n    result?.outcome !== 'applied' ||\n    !Array.isArray(observedLabels) ||\n    observedLabels.length !== labels.length ||\n    !labels.every(name => observedLabels.includes(name))\n  )\n    throw new Error('forge label-set read-back disagrees');\n  return applied;\n}\n",".shared/node-env.ts":"/**\n * The environment an exec node receives from the engine as its run contract: where\n * this run keeps its artifacts, which run it is, and the node's bound inputs.\n *\n * A project command a node runs on the project's behalf, such as its test gate, is\n * not part of the run and must not see these. A gate that sees `WORKFLOW_ID` believes\n * it is inside the run, and any Archon command it starts then acts for that run.\n *\n * The engine owns the list as `EXEC_NODE_ENVIRONMENT_NAMES`. A pack script cannot\n * import engine code, so a conformance test beside the engine holds this copy to it.\n */\nexport const NODE_CONTRACT_ENV: readonly string[] = [\n  'ARTIFACTS_DIR',\n  'STATE_DIR',\n  'LOG_DIR',\n  'ADOPTED_RUN_DIR',\n  'WORKFLOW_ID',\n  'BASE_BRANCH',\n  'USER_MESSAGE',\n  'ARGUMENTS',\n  'LOOP_USER_INPUT',\n  'LOOP_PREV_OUTPUT',\n  'REJECTION_REASON',\n  'CONTEXT',\n  'EXTERNAL_CONTEXT',\n  'ISSUE_CONTEXT',\n  'TYPED_ARTIFACTS_FILE',\n  'ARCHON_NODE_EXECUTION',\n];\n\n/** A node's `with:` bindings arrive with this prefix. */\nconst BINDING_PREFIX = 'INPUTS_';\n\n/** The node's environment without the run contract: what a project command should see. */\nexport function projectEnvironment(env: NodeJS.ProcessEnv): NodeJS.ProcessEnv {\n  const contract = new Set(NODE_CONTRACT_ENV);\n  return Object.fromEntries(\n    Object.entries(env).filter(([key]) => !contract.has(key) && !key.startsWith(BINDING_PREFIX))\n  );\n}\n",".shared/policy/triage.md":"# Triage policy\n\nThis is the SDLC pack's default triage policy. A project replaces it whole with its\nown `.archon/sdlc/policy/triage.md`, which may be nothing more than a pointer to\ndocuments the project already has.\n\n- **Scope.** Judge whether an item is in scope against the project's direction\n  document. When the project has none, say so rather than invent its scope.\n- **Closing without a person.** Only two kinds of item may be closed without a\n  maintainer: a duplicate of an item that is still open, and an item whose outcome a\n  merged change already delivered. Name that open item or that merged change.\n- **Everything else goes to a maintainer.** An item that looks closable for any other\n  reason (out of scope, obsolete, superseded, rejected by direction, or a duplicate of\n  a closed item) waits for a maintainer's decision, with the reason it looks closable.\n",".shared/pr.ts":"/**\n * The pack's pull-request reads and writes, through whichever source the run\n * selected (./forge.ts).\n *\n * Every write here is performed and then read back before it is reported as\n * applied. On the forge path the plugin owns that verification and reports which\n * of the four outcomes happened; on `gh` this module performs the same read-back\n * and raises the failure itself. Neither path falls back to the other, and an\n * operation whose outcome could not be established is never retried here.\n *\n * Authored content — a pull-request body, a review report — is passed by file\n * path on both paths, so it never reaches any process's argv.\n */\n\nimport { mkdtempSync, readFileSync, rmSync, writeFileSync } from 'node:fs';\nimport { tmpdir } from 'node:os';\nimport { join } from 'node:path';\nimport {\n  invokeForge,\n  parsePrRecord,\n  record,\n  sameRepo,\n  type ForgeSource,\n  type PrRecord,\n  type QualifiedPr,\n} from './forge.ts';\n\nexport interface PrView {\n  readonly pr: PrRecord;\n  readonly title: string;\n  readonly body: string;\n}\n\nexport interface CreatePrIntent {\n  readonly repo: QualifiedPr['repo'];\n  readonly headRepo: QualifiedPr['repo'];\n  readonly head: string;\n  readonly headRevision: string;\n  readonly base: string;\n  readonly title: string;\n  readonly bodyPath: string;\n  readonly draft: boolean;\n}\n\ninterface Ran {\n  readonly ok: boolean;\n  readonly stdout: string;\n  readonly stderr: string;\n}\n\n// Every gh call is captured: a node's stderr reaches the operator, and gh is\n// chatty there (update notices), so only this pack's own messages may.\nfunction gh(...args: string[]): Ran {\n  const result = Bun.spawnSync(['gh', ...args], { stdout: 'pipe', stderr: 'pipe' });\n  return {\n    ok: result.exitCode === 0,\n    stdout: result.stdout.toString().trim(),\n    stderr: result.stderr.toString().trim(),\n  };\n}\n\nfunction ghRepo(repo: QualifiedPr['repo']): string {\n  return `${repo.host}/${repo.path}`;\n}\n\nfunction required(result: Ran, what: string): string {\n  if (!result.ok) throw new Error(`${what} failed: ${result.stderr}`);\n  return result.stdout;\n}\n\nconst PR_FIELDS = [\n  'number',\n  'url',\n  'title',\n  'body',\n  'isDraft',\n  'state',\n  'baseRefName',\n  'headRefName',\n  'headRefOid',\n  'headRepository',\n  'headRepositoryOwner',\n  'maintainerCanModify',\n].join(',');\n\n/** One `gh pr view --json` row, narrowed to the fields this pack consumes. */\nfunction ghPrView(repo: QualifiedPr['repo'], value: unknown): PrView {\n  const row = record(value);\n  const headRepository = record(row?.headRepository);\n  const headOwner = record(row?.headRepositoryOwner);\n  const headPath =\n    typeof headRepository?.name === 'string' && typeof headOwner?.login === 'string'\n      ? `${headOwner.login}/${headRepository.name}`\n      : undefined;\n  const state = typeof row?.state === 'string' ? row.state.toLowerCase() : '';\n  return {\n    pr: parsePrRecord({\n      schemaVersion: 1,\n      repo,\n      number: row?.number,\n      url: row?.url,\n      head: row?.headRefName,\n      base: row?.baseRefName,\n      is_draft: row?.isDraft,\n      state,\n      head_repo: headPath === undefined ? null : { host: repo.host, path: headPath },\n      head_revision: typeof row?.headRefOid === 'string' && row.headRefOid !== '' ? row.headRefOid : null,\n      // gh does not report the base revision; the record keeps that absence explicit.\n      base_revision: null,\n      maintainer_can_modify:\n        typeof row?.maintainerCanModify === 'boolean' ? row.maintainerCanModify : null,\n    }),\n    title: typeof row?.title === 'string' ? row.title : '',\n    body: typeof row?.body === 'string' ? row.body : '',\n  };\n}\n\n/** A forge operation whose success always carries a result. */\nfunction forgeResult(op: string, request: Record<string, unknown>): Record<string, unknown> {\n  const value = invokeForge(op, request);\n  if (value === null) throw new Error(`forge ${op} returned no result`);\n  return value;\n}\n\nfunction forgePrView(value: Record<string, unknown>): PrView {\n  return {\n    pr: parsePrRecord(record(value)?.pr),\n    title: typeof value.title === 'string' ? value.title : '',\n    body: typeof value.body === 'string' ? value.body : '',\n  };\n}\n\n/**\n * The open pull request whose head is `headRepo:head` in `repo`, or undefined.\n *\n * \"Open\" is the question every caller here is actually asking: a branch that was\n * delivered and closed months ago must not stop a new pull request from opening,\n * and an open one must never be duplicated. More than one match is refused rather\n * than guessed at.\n */\nexport function findOpenPrByHead(\n  repo: QualifiedPr['repo'],\n  headRepo: QualifiedPr['repo'],\n  head: string,\n  source: ForgeSource\n): PrView | undefined {\n  if (source === 'forge') {\n    const value = invokeForge('pr.view', {\n      selector: { kind: 'head', repo, headRepo, head },\n    });\n    return value === null ? undefined : forgePrView(value);\n  }\n  const listed = gh(\n    'pr',\n    'list',\n    '--repo',\n    ghRepo(repo),\n    '--head',\n    head,\n    '--state',\n    'open',\n    '--json',\n    PR_FIELDS\n  );\n  const rows: unknown = JSON.parse(required(listed, 'gh pr list'));\n  if (!Array.isArray(rows)) throw new Error('gh pr list returned an unexpected payload');\n  // gh matches a head branch by name alone, so the qualified head repository is\n  // compared here; the forge selector already carries it.\n  const matches = rows\n    .map(row => ghPrView(repo, row))\n    .filter(view => view.pr.head_repo !== null && sameRepo(view.pr.head_repo, headRepo));\n  if (matches.length > 1) {\n    throw new Error(\n      `more than one open pull request in ${repo.path} has head ${headRepo.path}:${head}`\n    );\n  }\n  return matches[0];\n}\n\nexport function viewPr(ref: QualifiedPr, source: ForgeSource): PrView {\n  if (source === 'forge') {\n    const value = forgeResult('pr.view', {\n      selector: { kind: 'number', ref: { repo: ref.repo, number: ref.number } },\n    });\n    return forgePrView(value);\n  }\n  const result = gh(\n    'pr',\n    'view',\n    String(ref.number),\n    '--repo',\n    ghRepo(ref.repo),\n    '--json',\n    PR_FIELDS\n  );\n  return ghPrView(ref.repo, JSON.parse(required(result, `gh pr view ${String(ref.number)}`)));\n}\n\n/**\n * Open the pull request and return the record read back from the forge.\n *\n * A create that cannot be found again afterwards is reported as a pull request\n * that may exist, never as a failure that leaves the branch free to try again.\n */\nexport function createPr(intent: CreatePrIntent, source: ForgeSource): PrRecord {\n  if (source === 'forge') {\n    const value = forgeResult('pr.create', {\n      repo: intent.repo,\n      headRepo: intent.headRepo,\n      head: intent.head,\n      headRevision: intent.headRevision,\n      base: intent.base,\n      title: intent.title,\n      body: readFileSync(intent.bodyPath, 'utf8'),\n      draft: intent.draft,\n    });\n    return parsePrRecord(value.pr);\n  }\n  const body = readFileSync(intent.bodyPath, 'utf8');\n  const sameRepository = intent.headRepo.path === intent.repo.path;\n  const head = sameRepository ? intent.head : `${intent.headRepo.path.split('/')[0]}:${intent.head}`;\n  const created = gh(\n    'pr',\n    'create',\n    '--repo',\n    ghRepo(intent.repo),\n    '--base',\n    intent.base,\n    '--head',\n    head,\n    '--title',\n    intent.title,\n    '--body-file',\n    intent.bodyPath,\n    ...(intent.draft ? ['--draft'] : [])\n  );\n  if (!created.ok) throw new Error(`gh pr create failed: ${created.stderr}`);\n  const view = findOpenPrByHead(intent.repo, intent.headRepo, intent.head, source);\n  if (!view) {\n    throw new Error(\n      `gh pr create reported success but no open pull request has head ${intent.headRepo.path}:${intent.head}; a pull request may exist`\n    );\n  }\n  if (\n    view.title !== intent.title ||\n    view.body !== body ||\n    view.pr.head !== intent.head ||\n    view.pr.base !== intent.base ||\n    view.pr.head_revision !== intent.headRevision ||\n    view.pr.is_draft !== intent.draft ||\n    view.pr.state !== 'open'\n  ) {\n    throw new Error(\n      `the created pull request ${view.pr.url} does not match what was requested; it may need reconciling`\n    );\n  }\n  return view.pr;\n}\n\nexport function markPrDraft(ref: QualifiedPr, source: ForgeSource): PrRecord {\n  if (source === 'forge') {\n    const value = forgeResult('pr.draft', { ref: { repo: ref.repo, number: ref.number } });\n    return parsePrRecord(value.pr);\n  }\n  const before = viewPr(ref, source).pr;\n  if (before.state !== 'open') {\n    throw new Error(`${before.url} is ${before.state} and cannot be converted to draft`);\n  }\n  if (before.is_draft) return before;\n  const draft = gh('pr', 'ready', String(ref.number), '--repo', ghRepo(ref.repo), '--undo');\n  if (!draft.ok) throw new Error(`the draft conversion failed: ${draft.stderr}`);\n  const after = viewPr(ref, source).pr;\n  if (!after.is_draft || after.state !== 'open') {\n    throw new Error(`${after.url} does not report an open draft after conversion`);\n  }\n  return after;\n}\n\ninterface GhComment {\n  readonly id: string;\n  readonly body: string;\n  readonly url: string;\n}\n\nfunction ghIssueComments(ref: QualifiedPr): GhComment[] {\n  const comments: GhComment[] = [];\n  // Paged explicitly rather than through `gh api --paginate`, so what this reads\n  // does not depend on how gh chooses to join pages of a JSON array.\n  for (let page = 1; ; page++) {\n    const result = gh(\n      'api',\n      '--hostname',\n      ref.repo.host,\n      `repos/${ref.repo.path}/issues/${String(ref.number)}/comments?per_page=100&page=${String(page)}`\n    );\n    const rows: unknown = JSON.parse(required(result, 'gh api issue comments'));\n    if (!Array.isArray(rows)) throw new Error('gh api returned an unexpected comment payload');\n    for (const row of rows) {\n      const comment = record(row);\n      if (\n        comment === undefined ||\n        (typeof comment.id !== 'number' && typeof comment.id !== 'string') ||\n        typeof comment.html_url !== 'string'\n      ) {\n        throw new Error('gh api returned an unexpected comment payload');\n      }\n      comments.push({\n        id: String(comment.id),\n        body: typeof comment.body === 'string' ? comment.body : '',\n        url: comment.html_url,\n      });\n    }\n    if (rows.length < 100) return comments;\n  }\n}\n\n/**\n * Write the one comment carrying `marker` on its first line, creating it if it is\n * not there yet and replacing it in place when it is. More than one marked\n * comment is a conflict: guessing which one is canonical would silently abandon\n * the other.\n */\nexport function upsertComment(\n  ref: QualifiedPr,\n  marker: string,\n  bodyPath: string,\n  source: ForgeSource\n): { readonly url: string } {\n  const body = readFileSync(bodyPath, 'utf8');\n  if (source === 'forge') {\n    const value = forgeResult('comment.upsert', {\n      ref: { repo: ref.repo, number: ref.number },\n      marker,\n      body,\n    });\n    const comment = record(value.comment);\n    if (typeof comment?.url !== 'string') throw new Error('forge returned no verified comment');\n    return { url: comment.url };\n  }\n  if ((body.split(/\\r?\\n/, 1)[0] ?? '') !== marker) {\n    throw new Error('the comment body must begin with the exact canonical marker');\n  }\n  const marked = ghIssueComments(ref).filter(\n    comment => (comment.body.split(/\\r?\\n/, 1)[0] ?? '') === marker\n  );\n  if (marked.length > 1) {\n    throw new Error('more than one comment on this pull request carries the canonical marker');\n  }\n  const previous = marked[0];\n  if (previous?.body === body) return { url: previous.url };\n  // gh reads the body from a JSON request file: `-f body=@path` would post the\n  // literal string, and argv is not where authored content belongs.\n  const directory = mkdtempSync(join(tmpdir(), 'archon-comment-'));\n  let written: Ran;\n  try {\n    const payload = join(directory, 'comment.json');\n    writeFileSync(payload, JSON.stringify({ body }), { mode: 0o600 });\n    written = gh(\n      'api',\n      '--hostname',\n      ref.repo.host,\n      '--method',\n      previous ? 'PATCH' : 'POST',\n      previous\n        ? `repos/${ref.repo.path}/issues/comments/${previous.id}`\n        : `repos/${ref.repo.path}/issues/${String(ref.number)}/comments`,\n      '--input',\n      payload\n    );\n  } finally {\n    rmSync(directory, { recursive: true, force: true });\n  }\n  if (!written.ok) throw new Error(`gh api comment write failed: ${written.stderr}`);\n  const id = record(JSON.parse(written.stdout))?.id;\n  if (typeof id !== 'number' && typeof id !== 'string') {\n    throw new Error('gh api returned no comment identity; a comment may have changed');\n  }\n  const observed = ghIssueComments(ref).find(comment => comment.id === String(id));\n  if (observed?.body !== body) {\n    throw new Error(\n      `comment ${String(id)} does not read back as written; it may need reconciling`\n    );\n  }\n  return { url: observed.url };\n}\n",".shared/push.ts":"/**\n * Push the checkout's HEAD to a pull request's head branch, and prove it landed.\n *\n * This is publish-pr's push of the branch a pull request opens from. It names its\n * target explicitly — the head repository's remote (found by URL, ./remote.ts) and\n * the head branch — so git never picks an upstream. It never forces: a remote that moved refuses, and the refusal is\n * the evidence. A fork head no local remote names is pushed by its HTTPS URL, which\n * its author permits only when they allowed maintainer edits; the forge enforces that.\n * After the push, the remote ref is read back and must equal HEAD.\n */\n\nimport { sameRepo, type QualifiedPr } from './forge.ts';\nimport { git, gitOrThrow } from './git.ts';\nimport { findRemote, remoteFor } from './remote.ts';\n\nexport interface PushTarget {\n  readonly repo: QualifiedPr['repo'];\n  readonly head_repo: QualifiedPr['repo'] | null;\n  readonly head: string;\n}\n\n/** Push HEAD to `head` on the head repository; returns the pushed commit. */\nexport function pushHead(target: PushTarget): string {\n  const head = gitOrThrow('rev-parse', 'HEAD');\n  const fork = target.head_repo !== null && !sameRepo(target.head_repo, target.repo);\n  const headRepo = target.head_repo ?? target.repo;\n  const destination = fork\n    ? (findRemote(headRepo) ?? `https://${headRepo.host}/${headRepo.path}.git`)\n    : remoteFor(headRepo);\n  const ref = `refs/heads/${target.head}`;\n  const pushed = git('push', destination, `HEAD:${ref}`);\n  if (pushed.code !== 0) throw new Error(`git push ${destination} HEAD:${ref} refused: ${pushed.stderr}`);\n  const landed = gitOrThrow('ls-remote', destination, ref).split(/\\s+/)[0] ?? '';\n  if (landed !== head) {\n    throw new Error(`pushed ${head} to ${destination} ${ref}, but the remote reads ${landed || 'nothing'}`);\n  }\n  return head;\n}\n",".shared/remote.ts":"/**\n * Which git remote holds a repository, decided from each remote's URL, never its name.\n *\n * A checkout can be a fork (`origin`) beside the canonical repository (`upstream`), or\n * name its remotes anything at all. Every script that fetches a base or pushes a head\n * is handed the repository identity an agent resolved (`{host, path}`) and finds the\n * remote here, so no script assumes `origin`. URLs are a machine format: HTTPS,\n * `user@host:path` and `ssh://` forms reduce to the same identity, with credentials,\n * ports and a trailing `.git` dropped. The configured URL is read, before any\n * `url.<base>.insteadOf` rewrite: that is the repository the operator named.\n */\n\nimport { sameRepo, type QualifiedPr } from './forge.ts';\nimport { git } from './git.ts';\n\ntype Repo = QualifiedPr['repo'];\n\n/** The repository a remote URL names, or undefined for a local path or unknown form. */\nexport function urlRepo(url: string): Repo | undefined {\n  const trimmed = url.trim();\n  let host: string;\n  let path: string;\n  if (/^[a-z][a-z0-9+.-]*:\\/\\//i.test(trimmed)) {\n    let parsed: URL;\n    try {\n      parsed = new URL(trimmed);\n    } catch {\n      return undefined;\n    }\n    host = parsed.hostname;\n    path = parsed.pathname;\n  } else {\n    // scp-like `[user@]host:path`; a Windows drive path (`C:\\...`) is not a remote.\n    const scp = /^(?:[^@/]+@)?([^:/]+):(?!\\/\\/)(.+)$/.exec(trimmed);\n    if (!scp || scp[1].length === 1) return undefined;\n    host = scp[1];\n    path = scp[2];\n  }\n  // GitHub's SSH endpoint on port 443 serves the same repositories as github.com.\n  if (host === 'ssh.github.com') host = 'github.com';\n  path = path.replace(/^\\/+/, '').replace(/\\/+$/, '').replace(/\\.git$/, '');\n  if (host === '' || path === '' || !path.includes('/')) return undefined;\n  return { host, path };\n}\n\n/** The one remote whose URL names `repo`, undefined when none does; refuses on several. */\nexport function findRemote(repo: Repo): string | undefined {\n  const listed = git('config', '--get-regexp', '^remote\\\\..*\\\\.url$');\n  // Exit 1 means no remote is configured at all; anything else non-zero is a failure.\n  if (listed.code !== 0 && listed.code !== 1) {\n    throw new Error(`git config --get-regexp failed: ${listed.stderr}`);\n  }\n  const names = new Set<string>();\n  for (const line of listed.stdout.split('\\n')) {\n    const space = line.indexOf(' ');\n    if (space === -1) continue;\n    const named = urlRepo(line.slice(space + 1));\n    if (named && sameRepo(named, repo)) names.add(line.slice('remote.'.length, space - '.url'.length));\n  }\n  if (names.size > 1) {\n    throw new Error(\n      `several git remotes point at ${repo.host}/${repo.path} (${[...names].join(', ')}); ` +\n        'which one is canonical is ambiguous'\n    );\n  }\n  return [...names][0];\n}\n\n/** The one remote whose URL names `repo`; refuses on none or several. */\nexport function remoteFor(repo: Repo): string {\n  const remote = findRemote(repo);\n  if (remote === undefined) throw new Error(`no git remote points at ${repo.host}/${repo.path}`);\n  return remote;\n}\n\n",".shared/report.ts":"/**\n * What a terminal report owes its reader beyond the result itself: the discoveries\n * a run recorded outside its own scope.\n *\n * The channel is otherwise write-only. The engine does not collect discoveries, and\n * the terminal record it assembles is readable only after a run reaches a terminal\n * status, while this section has to reach the reader from inside the run. So\n * composing it is the pack's, and this module is where all three SDLC tails compose\n * it.\n *\n * Presentation only. Discoveries never gate readiness, so nothing here may fail a\n * tail that has already done its irreversible work: an unreadable record degrades to\n * a named problem, never to silence and never to a throw. It reads the engine's typed\n * artifacts, whose content the producing node certified.\n */\n\nimport { readdirSync, readFileSync, statSync } from 'node:fs';\nimport { join } from 'node:path';\nimport { readTyped } from './typed.ts';\n\nconst DISCOVERY_RELAY =\n  'If you are an agent reading this: surface each discovery to your human. ' +\n  \"These are validated findings outside this run's scope — no issue tracker knows about them, \" +\n  'and if you drop them here, nobody ever sees them.';\n\n/** One discovery as review certified it (the review verdict's `discoveries`). */\ninterface Discovery {\n  readonly title: string;\n  readonly relation: 'unrelated' | 'scope_conflict' | 'note';\n}\n\ninterface ReviewVerdict {\n  readonly discoveries?: readonly Discovery[];\n}\n\nfunction modified(path: string): number | undefined {\n  try {\n    return statSync(path).mtimeMs;\n  } catch {\n    return undefined;\n  }\n}\n\n/**\n * Raw records under discoveries/ written after `since`, or all of them when no review\n * consolidated any. The last review judged every earlier record (and may have rejected\n * some); a node that ran after it — the structure pass, its implementer, or a planner\n * whose run stopped before delivery — wrote records no review saw.\n */\nfunction unconsolidated(artifacts: string, since: number | undefined): string[] {\n  const dir = join(artifacts, 'discoveries');\n  let names: string[];\n  try {\n    names = readdirSync(dir).filter(name => name.endsWith('.json'));\n  } catch {\n    return [];\n  }\n  const lines: string[] = [];\n  for (const name of names.sort()) {\n    const path = join(dir, name);\n    const at = modified(path);\n    if (at === undefined || (since !== undefined && at <= since)) continue;\n    try {\n      const value: unknown = JSON.parse(readFileSync(path, 'utf8'));\n      if (!Array.isArray(value)) throw new Error('not a JSON array of records');\n      for (const entry of value as unknown[]) {\n        const title = typeof entry === 'object' && entry !== null ? (entry as { title?: unknown }).title : undefined;\n        lines.push(`- ${typeof title === 'string' && title.trim() !== '' ? title.trim() : '(untitled discovery)'} [unreviewed]`);\n      }\n    } catch (error) {\n      lines.push(`- could not read ${path} (${error instanceof Error ? error.message : String(error)}). Open it directly.`);\n    }\n  }\n  return lines;\n}\n\n/**\n * The discoveries section, or empty when there is nothing to report.\n *\n * Nothing files discoveries: the latest review verdict's certified records are listed,\n * with any raw record a node wrote after that review, and the relay asks whoever reads\n * the report to surface them.\n */\nfunction discoveries(artifacts: string, listingFile: string | undefined): string {\n  const read = readTyped<ReviewVerdict>(listingFile, artifacts, 'review-report');\n  if (read.listingProblem !== undefined) {\n    return `\\n\\nDiscoveries could not be listed: ${read.listingProblem} Open ${join(artifacts, 'discoveries.md')} and ${join(artifacts, 'discoveries')} directly.`;\n  }\n  const latest = read.entries?.at(-1);\n  const since = latest === undefined ? undefined : modified(join(artifacts, latest.path));\n  const lines = [\n    ...(read.values.at(-1)?.discoveries ?? []).map(record => `- ${record.title} [${record.relation}]`),\n    ...unconsolidated(artifacts, since),\n  ];\n  if (lines.length === 0) return '';\n  return (\n    `\\n\\nDiscoveries:\\n${lines.join('\\n')}\\n\\n` +\n    `Records: ${join(artifacts, 'discoveries.md')}, ${join(artifacts, 'discoveries')}\\n\\n${DISCOVERY_RELAY}`\n  );\n}\n\n/**\n * The report's closing section. `listingFile` is passed in rather than read from the\n * environment here, so the reusable report never silently depends on ambient state.\n */\nexport function caveats(\n  artifacts: string,\n  options: { readonly listingFile: string | undefined }\n): string {\n  return discoveries(artifacts, options.listingFile);\n}\n\n/**\n * The summary a tail's report node writes when a node failure kept the run from\n * reaching its outcome. It names no result: the engine's terminal record names the\n * failed node, and nothing here may read as a delivery.\n */\nexport function failed(\n  artifacts: string,\n  options: { readonly listingFile: string | undefined }\n): string {\n  return (\n    'Not done: a node failed before this run reported its result. The run\\'s terminal record names the node and its error. ' +\n    'Anything the run already published, such as a pushed branch or a pull request, is left as it is.' +\n    caveats(artifacts, options)\n  );\n}\n",".shared/review-policy.ts":"export const FULL_REVIEW_RISKS =\n  'Full review applies to wire formats and persisted contracts or schemas; concurrency over shared state; isolation, auth, security and credential boundaries; destructive or irreversible paths and data loss; integration boundaries; lifecycle ownership; and parsers over user-authored text. Uncertainty earns full review. Each engaged risk gets an explicit attempt to refute its invariant; a prose-only change gets the minimum.';\n\n/** The review lenses, in the order a route decision and a recorded lens set name them. */\nexport const REVIEW_LENSES = ['seams', 'code', 'tests', 'errors', 'docs'] as const;\nexport type ReviewLens = (typeof REVIEW_LENSES)[number];\n",".shared/scratch.ts":"/**\n * Remove the scratch worktrees reviewers created under this run.\n *\n * Read-only reviewers try mutations in scratch worktrees under\n * `$ARTIFACTS_DIR/scratch/<lens>/`. Cleanup is a workflow step, not a prompt\n * instruction, so a lens that died still has its tree removed. It touches only\n * registered worktrees whose real path is under the given scratch directory: never\n * the run's own checkout, another run's worktree, or a user's. It never runs a bare\n * `git worktree prune`, which would also drop unrelated missing registrations.\n */\n\nimport { existsSync, realpathSync, rmSync } from 'node:fs';\nimport { join, sep } from 'node:path';\n\n/** Remove every registered worktree under `scratch`, then the directory itself. */\nexport function pruneScratch(scratch: string): string[] {\n  if (!existsSync(scratch)) return [];\n  // The native resolver: on Windows it expands 8.3 short names (RUNNER~1), which git\n  // never prints, so both sides of the comparison name a directory the same way.\n  const root = realpathSync.native(scratch);\n  const listed = Bun.spawnSync(['git', 'worktree', 'list', '--porcelain'], {\n    stdout: 'pipe',\n    stderr: 'pipe',\n  });\n  if (listed.exitCode !== 0) {\n    throw new Error(`git worktree list failed: ${listed.stderr.toString().trim()}`);\n  }\n  const removed: string[] = [];\n  for (const line of listed.stdout.toString().split('\\n')) {\n    if (!line.startsWith('worktree ')) continue;\n    const path = line.slice('worktree '.length);\n    let real: string;\n    try {\n      real = realpathSync.native(path);\n    } catch {\n      real = path;\n    }\n    if (real !== root && !real.startsWith(root + sep)) continue;\n    const result = Bun.spawnSync(['git', 'worktree', 'remove', '--force', path], {\n      stdout: 'pipe',\n      stderr: 'pipe',\n    });\n    if (result.exitCode !== 0) {\n      throw new Error(`git worktree remove ${path} failed: ${result.stderr.toString().trim()}`);\n    }\n    removed.push(path);\n  }\n  // The directory as named, never its resolved target: a symlink there loses only the link.\n  rmSync(scratch, { recursive: true, force: true });\n  return removed;\n}\n\n/** `$ARTIFACTS_DIR/scratch`, or one lens's directory under it. */\nexport function scratchDir(artifacts: string, lens: string): string {\n  return lens === '' ? join(artifacts, 'scratch') : join(artifacts, 'scratch', lens);\n}\n",".shared/typed.ts":"/**\n * Read this run's typed artifacts of one type, in the order the engine produced them.\n *\n * The engine hands every exec node a listing at `TYPED_ARTIFACTS_FILE`: the current\n * run's artifacts grouped by their exact `output_type`, each with the path of its\n * content relative to `ARTIFACTS_DIR`, ordered by production time, plus every record\n * it could not read. A typed artifact's content is the producing node's certified\n * output, so a reader trusts its shape. What can still go wrong is reading it: a\n * missing listing, an unreadable content file, an engine diagnostic. Those come back\n * as `problems` for the caller to name, never as silence.\n */\n\nimport { readFileSync } from 'node:fs';\nimport { join } from 'node:path';\n\n/** One listed artifact's identity: the node that produced it and its loop position. */\nexport interface ListedArtifact {\n  readonly path: string;\n  readonly nodeId?: string;\n  readonly loopGroupPath?: readonly { readonly groupId: string; readonly iteration: number }[];\n}\n\nexport interface TypedRead<T> {\n  readonly values: readonly T[];\n  /** The listed artifacts the values were read from, in the same order. */\n  readonly entries?: readonly ListedArtifact[];\n  /** Records of this type, or engine diagnostics, that could not be read. */\n  readonly problems: readonly string[];\n  /** Set when the listing itself is missing or malformed: nothing in it can be trusted. */\n  readonly listingProblem?: string;\n}\n\nfunction isObject(value: unknown): value is Record<string, unknown> {\n  return typeof value === 'object' && value !== null && !Array.isArray(value);\n}\n\nexport function readTyped<T>(\n  listingFile: string | undefined,\n  artifacts: string,\n  type: string\n): TypedRead<T> {\n  const fail = (listingProblem: string): TypedRead<T> => ({ values: [], problems: [], listingProblem });\n  if (listingFile === undefined || listingFile === '') {\n    return fail('no typed-artifact listing reached this node.');\n  }\n  let listing: unknown;\n  try {\n    listing = JSON.parse(readFileSync(listingFile, 'utf8'));\n  } catch (error) {\n    const reason = error instanceof Error ? error.message : String(error);\n    return fail(`the typed-artifact listing ${listingFile} could not be read (${reason}).`);\n  }\n  // The listing is the engine's, read across a boundary this pack cannot import\n  // types over, so its envelope is checked rather than assumed.\n  if (!isObject(listing) || !isObject(listing.artifactsByType)) {\n    return fail(`the typed-artifact listing ${listingFile} is malformed: no artifactsByType object.`);\n  }\n  const entries = listing.artifactsByType[type] ?? [];\n  if (!Array.isArray(entries) || !entries.every(entry => isObject(entry) && typeof entry.path === 'string')) {\n    return fail(`the typed-artifact listing ${listingFile} is malformed: its ${type} entries are not records.`);\n  }\n  const values: T[] = [];\n  const problems: string[] = [];\n  const listed: ListedArtifact[] = entries as ListedArtifact[];\n  for (const entry of listed) {\n    const path = join(artifacts, entry.path);\n    try {\n      values.push(JSON.parse(readFileSync(path, 'utf8')) as T);\n    } catch (error) {\n      const reason = error instanceof Error ? error.message : String(error);\n      problems.push(`${path}: could not read this ${type} record (${reason})`);\n    }\n  }\n  const errors = listing.errors ?? [];\n  if (!Array.isArray(errors)) {\n    problems.push(`${listingFile}: the listing's \\`errors\\` value is not an array, so its diagnostics cannot be read`);\n  } else {\n    for (const error of errors.filter(isObject)) {\n      const code = typeof error.code === 'string' ? `, ${error.code}` : '';\n      problems.push(\n        `${typeof error.path === 'string' ? error.path : '(unknown record)'} (${typeof error.kind === 'string' ? error.kind : 'unreadable'}${code}): the engine could not read this record`\n      );\n    }\n  }\n  return { values, problems, entries: listed };\n}\n",".shared/verdict.ts":"/**\n * The one judgment this pack makes about a red gate: whether the declared cause is\n * one the change cannot have introduced.\n *\n * The vocabulary itself (`introduced`, `inherited`, `environment`, `interaction`,\n * `incomplete`, or the empty string for \"not declared\") is an enum on the producing\n * nodes' `output_format`, where the engine certifies it. Nothing here re-checks\n * membership: a value that reaches a script through a `with:` binding already passed\n * that gate.\n */\n\nexport const PASSES_RED = ['inherited', 'environment'] as const;\n\n/** Red that the change did not cause: the base was already red, or the environment was. */\nexport function passesRed(cause: string): boolean {\n  return (PASSES_RED as readonly string[]).includes(cause);\n}\n\n/**\n * The refusal for a verdict declared `incomplete`: some checks never ran, so the gate\n * has no complete answer. A check that did fail is named in the summary, but the\n * action is still to let validation finish: a partial red is not a verdict. Every\n * gate that reads a verdict refuses this cause with this one message.\n */\nexport function unfinishedValidation(stage: string, summary: string): string {\n  return (\n    `${stage}: validation didn't finish. Not every check ran.` +\n    `${summary === '' ? '' : ` ${summary}`} Resume the run once whatever ` +\n    'stopped it is cleared, so validation can finish. An unfinished validation ' +\n    'never passes this gate.'\n  );\n}\n",".shared/workitem.ts":"/**\n * The intake work item: one state document per issue, `work/<number>`, in the run's\n * project scope.\n *\n * The document is the item's state; its labels mirror it, and a label a person adds\n * is a request, never the state. Trust is decided once, by a script, from the\n * project's maintainer list, so no model and no workflow input can raise it. Every\n * event records a request on its item; a run then claims the best waiting item with\n * a conditional write, so two runs never work the same item, and releases the claim\n * when it is done. A claim whose run the engine reports terminal is released by the\n * next pickup; any other answer leaves it held, because a live owner and an orphan\n * cannot be told apart here.\n */\n\nimport { createHash } from 'node:crypto';\nimport { archonCommand, record, type QualifiedPr } from './forge.ts';\nimport { git, gitOrThrow } from './git.ts';\nimport { note } from './io.ts';\nimport {\n  type LabelVerdict,\n  type PackLabel,\n  isRequestLabel,\n  type Route,\n  type Size,\n  type WorkType,\n  wantedLabels,\n} from './labels.ts';\nimport { remoteFor } from './remote.ts';\n\nexport type Stage = 'new' | 'needs_maintainer' | Route | 'needs_contract' | 'blocked' | 'close';\n/** The trust and path vocabularies; a test proves archon-intake.yaml's enums agree. */\nexport const TRUSTS = ['maintainer', 'outside'] as const;\nexport type Trust = (typeof TRUSTS)[number];\nexport const INTAKE_PATHS = ['quiet', 'closed', 'outside', 'triage'] as const;\nexport const REQUEST_ACTIONS = ['opened', 'edited', 'reopened', 'added'] as const;\nexport type RequestAction = (typeof REQUEST_ACTIONS)[number];\n/** The `mode` and `trust` inputs. No trust input is `maintainer`, so no input can raise trust. */\nexport const INTAKE_MODES = ['live', 'eval'] as const;\nexport type IntakeMode = (typeof INTAKE_MODES)[number];\nexport const TRUST_INPUTS = ['auto', 'outside'] as const;\nexport type TrustInput = (typeof TRUST_INPUTS)[number];\n\nfunction oneOf<const Values extends readonly string[]>(\n  name: string,\n  values: Values,\n  text: string\n): Values[number] {\n  const value = text.trim() === '' ? values[0] : text.trim();\n  if (!values.includes(value)) {\n    throw new Error(`${name} must be one of ${values.join(', ')}, not \"${value}\"`);\n  }\n  return value as Values[number];\n}\n\n/** The `mode` input; empty means `live`. */\nexport function parseMode(text: string): IntakeMode {\n  return oneOf('mode', INTAKE_MODES, text);\n}\n\n/** The `trust` input; empty means `auto`. */\nexport function parseTrustInput(text: string): TrustInput {\n  return oneOf('trust', TRUST_INPUTS, text);\n}\n\n/** One event intake has not yet processed. A label request carries who added the label. */\nexport interface IntakeRequest {\n  readonly at: string;\n  readonly run_id: string;\n  readonly action: RequestAction;\n  readonly label: string | null;\n  readonly actor: string | null;\n  /** The body's digest when a label request was recorded: what a promotion pins. */\n  readonly body_digest: string | null;\n}\n\nexport interface Claim {\n  readonly run_id: string;\n  readonly at: string;\n  readonly requests: readonly IntakeRequest[];\n}\n\nexport interface Promotion {\n  readonly at: string;\n  readonly via: 'label';\n  readonly by: string;\n  readonly label: string;\n  readonly pin: { readonly body_digest: string };\n}\n\ninterface Field<Value extends string> {\n  readonly value: Value;\n  readonly reason: string;\n}\n\nexport interface TriageFacts {\n  readonly verdict: LabelVerdict;\n  readonly pull_request: number | null;\n  readonly type: Field<WorkType>;\n  readonly size: Field<Size>;\n  readonly complexity: Field<string>;\n  readonly importance: Field<string>;\n  readonly urgency: Field<string>;\n  readonly at: string;\n  readonly run_id: string;\n}\n\nexport interface HistoryEntry {\n  readonly at: string;\n  readonly stage: 'intake';\n  readonly run_id: string;\n  readonly outcome: string;\n  readonly summary: string;\n  readonly verdict?: string;\n  readonly report?: { readonly run_id: string; readonly path: string };\n}\n\nexport interface WorkItem {\n  readonly version: 1;\n  readonly subject: QualifiedPr;\n  readonly created_at: string;\n  readonly stage: Stage;\n  /** Null until intake first decides it; never changed after that. */\n  readonly trust: Trust | null;\n  readonly claim: Claim | null;\n  /** Requests waiting for intake. A non-empty list is what makes the item a candidate. */\n  readonly requests: readonly IntakeRequest[];\n  readonly links: { readonly runs: readonly string[] };\n  readonly promoted: Promotion | null;\n  readonly facts: {\n    readonly intake?: {\n      readonly body_digest: string;\n      readonly at: string;\n      readonly run_id: string;\n      /** The request labels the last pickup left waiting for their requests. */\n      readonly waiting: readonly string[];\n    };\n    readonly triage?: TriageFacts;\n  };\n  readonly history: readonly HistoryEntry[];\n}\n\n/** What the facts node decided for the item it claimed, handed to the outcome node. */\nexport interface IntakeDecision {\n  readonly path: (typeof INTAKE_PATHS)[number];\n  readonly trust: Trust | null;\n  readonly promoted: Promotion | null;\n  readonly stage: Stage;\n  readonly body_digest: string;\n  /**\n   * The issue's labels at pickup that are this run's to remove; the outcome removes\n   * only owned labels among them.\n   */\n  readonly labels: readonly string[];\n  /** The request labels on the issue that wait for a request not yet recorded. */\n  readonly waiting: readonly string[];\n  readonly notes: readonly HistoryEntry[];\n}\n\n/** Triage's verdict as the outcome node receives it. */\nexport interface TriageResult extends Omit<TriageFacts, 'at' | 'run_id'> {\n  readonly labels: readonly string[];\n  readonly summary: string;\n  readonly report: { readonly run_id: string; readonly path: string };\n}\n\nexport const MAINTAINERS_PATH = '.archon/sdlc/policy/maintainers.json';\n// History, run links and label requests are capped so a label-spamming account cannot\n// push the document past the state store's 64 KiB limit and wedge the item. `archon\n// state log` keeps every revision.\nconst KEPT = 50;\n\nconst STAGES = {\n  new: true,\n  needs_maintainer: true,\n  investigate: true,\n  plan: true,\n  deliver: true,\n  continue: true,\n  needs_contract: true,\n  blocked: true,\n  close: true,\n} as const satisfies Record<Stage, true>;\n\nexport function workItemName(number: number): string {\n  return `work/${String(number)}`;\n}\n\nexport function bodyDigest(body: string): string {\n  return `sha256:${createHash('sha256').update(body, 'utf8').digest('hex')}`;\n}\n\nfunction newest<T>(entries: readonly T[]): T[] {\n  return entries.slice(-KEPT);\n}\n\nfunction isLabelRequest(request: IntakeRequest): boolean {\n  return request.action === 'added';\n}\n\n/**\n * Only label requests carry anything a decision reads; any other request just makes\n * the item a candidate, and the pickup reads the live issue. So one of those is kept,\n * however often an author edits.\n */\nfunction queued(requests: readonly IntakeRequest[]): IntakeRequest[] {\n  const other = requests.filter(request => !isLabelRequest(request)).at(-1);\n  return newest(requests.filter(request => isLabelRequest(request) || request === other));\n}\n\nexport function newWorkItem(subject: QualifiedPr, at: string): WorkItem {\n  return {\n    version: 1,\n    subject,\n    created_at: at,\n    stage: 'new',\n    trust: null,\n    claim: null,\n    requests: [],\n    links: { runs: [] },\n    promoted: null,\n    facts: {},\n    history: [],\n  };\n}\n\n/** A stored document, checked as far as intake reads it. */\nexport function parseWorkItem(value: unknown): WorkItem {\n  const doc = record(value);\n  const subject = record(doc?.subject);\n  const repo = record(subject?.repo);\n  const claim = doc?.claim === null ? null : record(doc?.claim);\n  if (\n    doc?.version !== 1 ||\n    typeof repo?.host !== 'string' ||\n    typeof repo.path !== 'string' ||\n    typeof subject?.number !== 'number' ||\n    typeof doc.created_at !== 'string' ||\n    typeof doc.stage !== 'string' ||\n    !Object.hasOwn(STAGES, doc.stage) ||\n    !(doc.trust === null || (TRUSTS as readonly unknown[]).includes(doc.trust)) ||\n    claim === undefined ||\n    (claim !== null && (typeof claim.run_id !== 'string' || !Array.isArray(claim.requests))) ||\n    !Array.isArray(doc.requests) ||\n    !Array.isArray(record(doc.links)?.runs) ||\n    !(doc.promoted === null || record(doc.promoted) !== undefined) ||\n    record(doc.facts) === undefined ||\n    !Array.isArray(doc.history)\n  ) {\n    throw new Error('not a version 1 intake work item');\n  }\n  return doc as unknown as WorkItem;\n}\n\n// --- ordering -----------------------------------------------------------------\n\n/**\n * Rank orders for the ordering keys. Each list is the triage node's own enum for\n * that field, lowest first; a test proves the two agree.\n */\nexport const RANKS = {\n  urgency: ['none', 'soon', 'now'],\n  importance: ['low', 'medium', 'high'],\n  size: ['s', 'm', 'l'],\n  complexity: ['low', 'medium', 'high'],\n} as const;\ntype RankedKey = keyof typeof RANKS;\nexport interface OrderKey {\n  readonly key: RankedKey | 'created';\n  readonly direction: 'asc' | 'desc';\n}\n\nexport const DEFAULT_ORDER = '[\"urgency desc\",\"importance desc\",\"size asc\",\"created asc\"]';\n\n/** The `order` input: a JSON array of `\"<key> <asc|desc>\"`. Anything else refuses. */\nexport function parseOrder(text: string): OrderKey[] {\n  let parsed: unknown;\n  try {\n    parsed = JSON.parse(text.trim() === '' ? DEFAULT_ORDER : text);\n  } catch {\n    throw new Error('order is not a JSON array');\n  }\n  if (!Array.isArray(parsed)) throw new Error('order is not a JSON array');\n  return parsed.map(entry => {\n    const [key, direction, ...rest] = typeof entry === 'string' ? entry.split(' ') : [];\n    if (\n      rest.length > 0 ||\n      !(key === 'created' || Object.hasOwn(RANKS, key ?? '')) ||\n      (direction !== 'asc' && direction !== 'desc')\n    ) {\n      throw new Error(\n        `order entry ${JSON.stringify(entry)} is not \"<urgency|importance|size|complexity|created> <asc|desc>\"`\n      );\n    }\n    return { key: key as OrderKey['key'], direction };\n  });\n}\n\nfunction sortValue(doc: WorkItem, key: OrderKey['key']): number | string | undefined {\n  if (key === 'created') return doc.created_at;\n  const value = doc.facts.triage?.[key].value;\n  if (value === undefined) return undefined;\n  const rank = (RANKS[key] as readonly string[]).indexOf(value);\n  return rank === -1 ? undefined : rank;\n}\n\n/**\n * Whether the item's last attempt ended without recording an outcome: a pickup\n * released its claim after the item's latest recorded decision.\n */\nexport function lastAttemptFailed(doc: WorkItem): boolean {\n  const released = doc.history.filter(entry => entry.outcome === 'released').at(-1);\n  return released !== undefined && released.at > (doc.facts.intake?.at ?? '');\n}\n\n/**\n * Order candidates by the keys, then by issue number. An item whose last attempt\n * failed sorts after every other, so an item that cannot be read or labelled is\n * retried without starving the rest. An item with no value for a key sorts after\n * every item that has one, whichever the direction, so untriaged items fall back to\n * the later keys.\n */\nexport function sortCandidates<T extends { readonly doc: WorkItem }>(\n  candidates: readonly T[],\n  order: readonly OrderKey[]\n): T[] {\n  return [...candidates].sort((left, right) => {\n    const failed = Number(lastAttemptFailed(left.doc)) - Number(lastAttemptFailed(right.doc));\n    if (failed !== 0) return failed;\n    for (const { key, direction } of order) {\n      const a = sortValue(left.doc, key);\n      const b = sortValue(right.doc, key);\n      if (a === b) continue;\n      if (a === undefined) return 1;\n      if (b === undefined) return -1;\n      const ascending = a < b ? -1 : 1;\n      return direction === 'asc' ? ascending : -ascending;\n    }\n    return left.doc.subject.number - right.doc.subject.number;\n  });\n}\n\n/** Whether a pickup may release a claim, from the claiming run's status. */\nexport function claimDisposition(status: string | null): 'hold' | 'release' {\n  return status === 'completed' || status === 'failed' || status === 'cancelled'\n    ? 'release'\n    : 'hold';\n}\n\n// --- labels -------------------------------------------------------------------\n\nexport function stageFromVerdict(verdict: LabelVerdict): Stage {\n  switch (verdict.contract) {\n    case 'READY':\n      return verdict.route;\n    case 'NEEDS_CONTRACT_WORK':\n      return 'needs_contract';\n    case 'BLOCKED':\n      return 'blocked';\n    case 'NO_ACTION':\n      return 'close';\n  }\n}\n\n/** The pack labels the document says the issue carries. */\nexport function mirrorLabels(doc: WorkItem): PackLabel[] {\n  if (doc.stage === 'needs_maintainer') return ['archon-needs-maintainer'];\n  const triage = doc.facts.triage;\n  if (doc.stage === 'new' || triage === undefined) return [];\n  return wantedLabels(triage.verdict, triage.type.value, triage.size.value);\n}\n\nfunction promotedAt(promoted: Promotion | null, digest: string): boolean {\n  return promoted !== null && promoted.pin.body_digest === digest;\n}\n\n/**\n * The install's own forge identity must never promote an outside item, so the\n * outcome node refuses to add a request label to one that is not promoted at the\n * body it just recorded.\n */\nexport function assertNoSelfPromotion(doc: WorkItem, add: readonly string[]): void {\n  const digest = doc.facts.intake?.body_digest ?? '';\n  if (doc.trust === 'outside' && !promotedAt(doc.promoted, digest)) {\n    const promoting = add.filter(isRequestLabel);\n    if (promoting.length > 0) {\n      throw new Error(\n        `refusing to add ${promoting.join(', ')} to an outside item no maintainer promoted`\n      );\n    }\n  }\n}\n\n// --- the decision ---------------------------------------------------------------\n\nexport interface IssueFacts {\n  /** Undefined when the selected source does not report authors. */\n  readonly author: string | null | undefined;\n  readonly labels: readonly string[];\n  readonly state: 'open' | 'closed';\n  readonly digest: string;\n}\n\nexport function isMaintainer(login: string | null, maintainers: ReadonlySet<string>): boolean {\n  return login !== null && login !== '' && maintainers.has(login.toLowerCase());\n}\n\n/**\n * Decide what the claimed item needs, from the document, its claimed requests and\n * the live issue. Pure: the outcome node applies the result.\n *\n * `trustInput: 'outside'` decides an item with no recorded trust as outside without\n * reading its author. It never rewrites recorded trust, so it refuses an item already\n * recorded as a maintainer's. Label actors are still checked against the real list.\n */\nexport function decideIntake(\n  doc: WorkItem,\n  issue: IssueFacts,\n  maintainers: ReadonlySet<string>,\n  at: string,\n  runId: string,\n  trustInput: TrustInput = 'auto'\n): IntakeDecision {\n  let trust = doc.trust;\n  let promoted = doc.promoted;\n  const notes: HistoryEntry[] = [];\n  const mirror = new Set<string>(mirrorLabels(doc));\n  const claimed = new Set((doc.claim?.requests ?? []).map(request => request.label));\n  const waited = new Set(doc.facts.intake?.waiting ?? []);\n  // A request label this run neither claimed a request for nor wrote itself may have\n  // a request on its way, landing at any point of this run or after it, so the label\n  // waits for the run that claims it. It waits one pickup: a label still unclaimed\n  // after that has no request coming. On a maintainer's item only archon-triage\n  // waits, because any route label's request is reconciled away.\n  const waits = (label: string): boolean =>\n    isRequestLabel(label) &&\n    !mirror.has(label) &&\n    !claimed.has(label) &&\n    !waited.has(label) &&\n    (trust !== 'maintainer' || label === 'archon-triage');\n  const noted = (outcome: string, summary: string): void => {\n    notes.push({ at, stage: 'intake', run_id: runId, outcome, summary });\n  };\n  const quiet = (stage: Stage = doc.stage): IntakeDecision => ({\n    path: 'quiet',\n    trust,\n    promoted,\n    stage,\n    body_digest: issue.digest,\n    labels: issue.labels.filter(label => !waits(label)),\n    waiting: issue.labels.filter(waits),\n    notes,\n  });\n  if (issue.state === 'closed') {\n    noted('closed', 'the issue is closed; intake changes nothing on it');\n    return { ...quiet(), path: 'closed' };\n  }\n  if (trustInput === 'outside' && trust === 'maintainer') {\n    throw new Error(\n      \"trust: outside cannot lower trust this item already recorded as maintainer; a work item's trust is decided once\"\n    );\n  }\n  if (trust === null && trustInput === 'outside') {\n    trust = 'outside';\n  } else if (trust === null) {\n    if (issue.author === undefined) {\n      throw new Error(\n        'the selected forge source does not report issue authors, so trust cannot be decided'\n      );\n    }\n    trust = isMaintainer(issue.author, maintainers) ? 'maintainer' : 'outside';\n  }\n\n  if (promoted !== null && !promotedAt(promoted, issue.digest)) {\n    noted(\n      'demoted',\n      `the body changed after promotion (pinned ${promoted.pin.body_digest}, now ${issue.digest})`\n    );\n    promoted = null;\n  }\n\n  let retriage = false;\n  let promotedNow = false;\n  for (const request of doc.claim?.requests ?? []) {\n    const label = request.label;\n    if (request.action !== 'added' || label === null || !isRequestLabel(label)) continue;\n    // The pack writes the work item before any label, so a label already in the\n    // document's mirror is the pack's own write coming back as an event.\n    if (mirror.has(label)) continue;\n    if (!issue.labels.includes(label)) {\n      noted('void', `${label} was removed before intake read it`);\n      continue;\n    }\n    if (!isMaintainer(request.actor, maintainers)) {\n      noted(\n        'refused',\n        `${label} added by ${request.actor || 'an unknown account'}, who is not a listed maintainer; it promotes nothing`\n      );\n      continue;\n    }\n    if (trust === 'maintainer') {\n      if (label === 'archon-triage') retriage = true;\n      else\n        noted(\n          'reconciled',\n          `${label} added by ${request.actor} disagrees with the work item and is removed; add archon-triage to re-triage`\n        );\n      continue;\n    }\n    if (request.body_digest !== issue.digest) {\n      noted(\n        'refused',\n        `${label} added by ${request.actor}, but the body changed after the request; add the label again`\n      );\n      continue;\n    }\n    promoted = {\n      at,\n      via: 'label',\n      by: request.actor as string,\n      label,\n      pin: { body_digest: issue.digest },\n    };\n    promotedNow = true;\n    noted('promoted', `${label} added by ${request.actor} promotes this outside item`);\n  }\n\n  const triage = (): IntakeDecision => ({ ...quiet(), path: 'triage' });\n  if (trust === 'maintainer') {\n    return doc.facts.triage === undefined || retriage ? triage() : quiet();\n  }\n  if (promotedNow) return triage();\n  if (!promotedAt(promoted, issue.digest)) {\n    return { ...quiet('needs_maintainer'), path: 'outside' };\n  }\n  return quiet();\n}\n\n/**\n * The document after the outcome node applies a decision. Built on the fresh read,\n * so requests appended while this run worked stay queued.\n */\nexport function applyDecision(\n  doc: WorkItem,\n  decision: IntakeDecision,\n  triage: TriageResult | null,\n  /** The body changed while a promoted outside item was being triaged. */\n  bodyMoved: boolean,\n  at: string,\n  runId: string\n): WorkItem {\n  const history: HistoryEntry[] = [...doc.history, ...decision.notes];\n  let stage = decision.stage;\n  let promoted = decision.promoted;\n  let facts = {\n    ...doc.facts,\n    intake: { body_digest: decision.body_digest, at, run_id: runId, waiting: decision.waiting },\n  };\n  if (decision.path === 'triage') {\n    if (triage === null) throw new Error('the triage path has no triage verdict');\n    const { verdict, pull_request, type, size, complexity, importance, urgency, summary, report } =\n      triage;\n    facts = {\n      ...facts,\n      triage: {\n        verdict,\n        pull_request,\n        type,\n        size,\n        complexity,\n        importance,\n        urgency,\n        at,\n        run_id: runId,\n      },\n    };\n    if (bodyMoved) {\n      stage = 'needs_maintainer';\n      promoted = null;\n      history.push({\n        at,\n        stage: 'intake',\n        run_id: runId,\n        outcome: 'demoted',\n        summary: 'the body changed during triage; the promotion no longer holds',\n        report,\n      });\n    } else {\n      stage = stageFromVerdict(triage.verdict);\n      history.push({\n        at,\n        stage: 'intake',\n        run_id: runId,\n        outcome: stage,\n        verdict: triage.verdict.contract,\n        summary,\n        report,\n      });\n    }\n  } else if (decision.path === 'outside' && doc.stage !== 'needs_maintainer') {\n    history.push({\n      at,\n      stage: 'intake',\n      run_id: runId,\n      outcome: 'needs_maintainer',\n      summary: 'the author is not a listed maintainer; waiting for a maintainer to promote it',\n    });\n  }\n  return {\n    ...doc,\n    stage,\n    trust: decision.trust,\n    promoted,\n    facts,\n    history: newest(history),\n    links: { runs: newest([...doc.links.runs.filter(id => id !== runId), runId]) },\n  };\n}\n\n// --- the maintainer list ------------------------------------------------------------\n\n/** The maintainer list's text, lower-cased logins; anything but an array of logins refuses. */\nexport function parseMaintainers(text: string): Set<string> {\n  let parsed: unknown;\n  try {\n    parsed = JSON.parse(text);\n  } catch {\n    throw new Error(`${MAINTAINERS_PATH} is not valid JSON`);\n  }\n  if (\n    !Array.isArray(parsed) ||\n    !parsed.every(login => typeof login === 'string' && login.trim() !== '')\n  ) {\n    throw new Error(`${MAINTAINERS_PATH} must be a JSON array of forge logins`);\n  }\n  return new Set(parsed.map(login => (login as string).trim().toLowerCase()));\n}\n\n/**\n * The maintainer list at the head of the repository's default branch, read with git\n * so it works on either forge source and whatever branch the checkout sits on. No\n * file means nobody: every author is outside.\n */\nexport function readMaintainers(repo: QualifiedPr['repo']): Set<string> {\n  const remote = remoteFor(repo);\n  const head = gitOrThrow('ls-remote', '--symref', remote, 'HEAD');\n  const branch = /^ref: refs\\/heads\\/(\\S+)\\tHEAD$/m.exec(head)?.[1];\n  if (branch === undefined) throw new Error(`${remote} reports no default branch`);\n  const ref = `refs/remotes/${remote}/${branch}`;\n  gitOrThrow('fetch', '--quiet', '--no-tags', remote, `+refs/heads/${branch}:${ref}`);\n  if (git('cat-file', '-e', `${ref}:${MAINTAINERS_PATH}`).code !== 0) return new Set();\n  return parseMaintainers(gitOrThrow('show', `${ref}:${MAINTAINERS_PATH}`));\n}\n\n// --- the state store ------------------------------------------------------------\n\nconst STATE_CONFLICT = 3;\n\nfunction archon(args: readonly string[], input?: string): { code: number; value: unknown } {\n  const result = Bun.spawnSync([...archonCommand(), ...args], {\n    // Bun spawns with the environment as the process started unless given the live one.\n    env: process.env,\n    stdin: input === undefined ? 'ignore' : Buffer.from(input),\n    stdout: 'pipe',\n    stderr: 'pipe',\n  });\n  let value: unknown;\n  try {\n    value = JSON.parse(result.stdout.toString());\n  } catch {\n    value = undefined;\n  }\n  return { code: result.exitCode, value };\n}\n\nfunction failed(what: string, result: { code: number; value: unknown }): Error {\n  const message = record(result.value)?.error;\n  return new Error(\n    `archon ${what} failed (exit ${String(result.code)})${typeof message === 'string' ? `: ${message}` : ''}`\n  );\n}\n\nexport interface Stored {\n  readonly revision: number;\n  readonly value: unknown;\n}\n\nexport function stateGet(name: string): Stored {\n  const result = archon(['state', 'get', name]);\n  const value = record(result.value);\n  if (result.code !== 0 || typeof value?.revision !== 'number')\n    throw failed(`state get ${name}`, result);\n  return { revision: value.revision, value: value.value ?? null };\n}\n\n/** A conditional replace: `conflict` when the document moved past `ifRevision`. */\nexport function statePut(name: string, value: unknown, ifRevision: number): 'ok' | 'conflict' {\n  const result = archon(\n    ['state', 'put', name, '--if-revision', String(ifRevision)],\n    JSON.stringify(value)\n  );\n  if (result.code === STATE_CONFLICT) return 'conflict';\n  if (result.code !== 0) throw failed(`state put ${name}`, result);\n  return 'ok';\n}\n\n/** Append to an array in the latest revision; appends never conflict. */\nexport function stateAppend(name: string, path: string, value: unknown): void {\n  const result = archon(\n    ['state', 'patch', name],\n    JSON.stringify({ ops: [{ op: 'append', path, value }] })\n  );\n  if (result.code !== 0) throw failed(`state patch ${name}`, result);\n}\n\nexport function stateList(prefix: string): string[] {\n  const result = archon(['state', 'list', '--prefix', prefix]);\n  const documents = record(result.value)?.documents;\n  if (result.code !== 0 || !Array.isArray(documents)) throw failed('state list', result);\n  return documents\n    .map(record)\n    .filter(row => row?.deleted === false && typeof row.name === 'string')\n    .map(row => row?.name as string);\n}\n\n/** The run's status as the engine reports it, or null when it gives no status. */\nexport function runStatus(runId: string): string | null {\n  const status = record(archon(['workflow', 'get', runId, '--json']).value)?.status;\n  return typeof status === 'string' ? status : null;\n}\n\n// --- pickup ---------------------------------------------------------------------\n\n/**\n * Record a request on the item that sent it, creating the item's document if needed.\n * A request that is not a label adds nothing while another such request waits.\n */\nexport function enqueue(subject: QualifiedPr, request: IntakeRequest): void {\n  const name = workItemName(subject.number);\n  const stored = stateGet(name);\n  if (stored.value === null) {\n    const created = { ...newWorkItem(subject, request.at), requests: [request] };\n    if (statePut(name, created, stored.revision) === 'ok') return;\n  }\n  const waiting = record(stored.value)?.requests;\n  if (\n    !isLabelRequest(request) &&\n    Array.isArray(waiting) &&\n    waiting.some(entry => record(entry)?.action !== 'added')\n  )\n    return;\n  stateAppend(name, '/requests', request);\n}\n\nexport interface Read {\n  readonly name: string;\n  readonly revision: number;\n  readonly doc: WorkItem;\n}\n\nfunction read(name: string): Read | undefined {\n  const stored = stateGet(name);\n  if (stored.value === null) return undefined;\n  try {\n    return { name, revision: stored.revision, doc: parseWorkItem(stored.value) };\n  } catch (error) {\n    note(`intake skips ${name}: ${error instanceof Error ? error.message : String(error)}`);\n    return undefined;\n  }\n}\n\n/**\n * Release a claim whose run the engine reports terminal; any other answer holds it.\n * A run that finishes clears its own claim, so a terminal run still holding one\n * stopped before its labels were written, and its requests wait again.\n */\nfunction releaseIfTerminal(item: Read, at: string, runId: string): Read {\n  const claim = item.doc.claim;\n  if (claim === null) return item;\n  const status = runStatus(claim.run_id);\n  if (claimDisposition(status) === 'hold') {\n    if (status === null) {\n      note(\n        `intake leaves ${item.name} claimed: the engine reports no status for run ${claim.run_id}`\n      );\n    }\n    return item;\n  }\n  const doc: WorkItem = {\n    ...item.doc,\n    claim: null,\n    requests: queued([...claim.requests, ...item.doc.requests]),\n    history: newest([\n      ...item.doc.history,\n      {\n        at,\n        stage: 'intake',\n        run_id: runId,\n        outcome: 'released',\n        summary: `released the claim of run ${claim.run_id}, which ended ${String(status)} without finishing its outcome; its requests wait again`,\n      },\n    ]),\n  };\n  return statePut(item.name, doc, item.revision) === 'ok'\n    ? { ...item, revision: item.revision + 1, doc }\n    : item;\n}\n\nfunction claimed(item: Read, at: string, runId: string): WorkItem {\n  return {\n    ...item.doc,\n    claim: { run_id: runId, at, requests: queued(item.doc.requests) },\n    requests: [],\n  };\n}\n\nfunction claimable(item: Read | undefined): item is Read {\n  return item !== undefined && item.doc.claim === null && item.doc.requests.length > 0;\n}\n\n/**\n * Release terminal claims, then claim the first waiting item in `order` with a\n * conditional write. A conflict re-reads the item once and claims it only if it\n * still waits unclaimed; otherwise the next candidate is tried.\n */\nexport function claimNext(order: readonly OrderKey[], at: string, runId: string): WorkItem | null {\n  const items = stateList('work/')\n    .map(read)\n    .filter((item): item is Read => item !== undefined)\n    .map(item => releaseIfTerminal(item, at, runId));\n  for (const candidate of sortCandidates(items.filter(claimable), order)) {\n    const won = claimItem(candidate, at, runId);\n    if (won !== null) return won;\n  }\n  return null;\n}\n\nexport function claimItem(candidate: Read, at: string, runId: string): WorkItem | null {\n  const doc = claimed(candidate, at, runId);\n  if (statePut(candidate.name, doc, candidate.revision) === 'ok') return doc;\n  const fresh = read(candidate.name);\n  if (!claimable(fresh)) return null;\n  const retried = claimed(fresh, at, runId);\n  return statePut(fresh.name, retried, fresh.revision) === 'ok' ? retried : null;\n}\n\n/**\n * Replace the document of the item this run holds, re-reading on a conflict. Refuses\n * when the claim is no longer this run's, for example after a failed run's claim was\n * released and the run was then resumed.\n */\nexport function updateClaimed(\n  subject: QualifiedPr,\n  runId: string,\n  change: (doc: WorkItem) => WorkItem\n): WorkItem {\n  const name = workItemName(subject.number);\n  // Enqueues append to the document at any time, so a conflict is ordinary here.\n  for (let attempt = 0; attempt < 3; attempt++) {\n    const stored = stateGet(name);\n    const doc = parseWorkItem(stored.value);\n    if (doc.claim?.run_id !== runId) throw new Error(`${name} is no longer claimed by this run`);\n    const changed = change(doc);\n    const next = { ...changed, requests: queued(changed.requests) };\n    if (statePut(name, next, stored.revision) === 'ok') return next;\n  }\n  throw new Error(`${name} kept changing: three conditional writes conflicted`);\n}\n","deliver/scripts/outcome.ts":"/**\n * The delivery tail's result when the rounds ran to an ending: ready, or not ready\n * and why. The `report` node relays it as the workflow's return.\n *\n * The last round's typed ending is the result: ready when its review converged and\n * the CI agent saw green and marked the pull request ready, otherwise the reason the\n * rounds stopped, in the deciding node's words. Either way it lists the contract\n * items the latest review left open, then the discoveries the run recorded for the\n * operator.\n *\n * Bound inputs (`with:` bindings, canonical text in env):\n * - INPUTS_ROUNDS: the rounds loop's final `round` output.\n */\n\nimport { artifactsDir, emit, text } from '../../.shared/io.ts';\nimport { caveats } from '../../.shared/report.ts';\n\nconst rounds = JSON.parse(text(process.env.INPUTS_ROUNDS)) as {\n  ready: boolean;\n  reason: string;\n  pr_url: string;\n  ci_rerun: string;\n  contract_left: string[] | null;\n  summary: string;\n};\nconst notes = caveats(artifactsDir(), { listingFile: process.env.TYPED_ARTIFACTS_FILE });\nconst where = rounds.pr_url === '' ? '' : `\\n${rounds.pr_url}`;\nconst left = rounds.contract_left?.length\n  ? `\\n\\nLeft open, so the pull request does not close its issue:\\n${rounds.contract_left.map(item => `- ${item}`).join('\\n')}`\n  : '';\n\nemit({\n  ready: rounds.ready,\n  reason: rounds.reason,\n  pr_url: rounds.pr_url,\n  ci_rerun: rounds.ci_rerun,\n  summary: `${rounds.ready ? 'Ready' : 'Not ready'}: ${rounds.summary}${where}${left}${notes}`,\n});\n","deliver/scripts/report.ts":"/**\n * The delivery tail's terminal report on every ending, a node failure included.\n *\n * When the outcome node ran, its report passes through unchanged. When a node failure\n * kept it from running, the report is not ready with reason `failed`; the run still\n * fails, and its terminal record names the node that failed.\n *\n * Bound inputs (`with:` bindings, canonical text in env):\n * - INPUTS_OUTCOME: the outcome node's report, or \"null\" when a node failure kept it\n *   from running.\n */\n\nimport { artifactsDir, emit, nullableJson } from '../../.shared/io.ts';\nimport { failed } from '../../.shared/report.ts';\n\nconst outcome = nullableJson(process.env.INPUTS_OUTCOME);\nemit(\n  outcome ?? {\n    ready: false,\n    reason: 'failed',\n    pr_url: '',\n    ci_rerun: 'none',\n    summary: failed(artifactsDir(), { listingFile: process.env.TYPED_ARTIFACTS_FILE }),\n  }\n);\n","deliver/scripts/round.ts":"/**\n * One delivery round's typed result, and whether the round loop is done.\n *\n * A loop_group that exhausts max_iterations fails the run instead of ending it with\n * a reason, so this node counts rounds itself and declares the run done at ROUND_CAP.\n * Everything else is read from the round's own typed outputs; nothing here judges.\n * It also says whether the next round's review is light: after a CI fix, the\n * general code reviewer alone on the delta; otherwise the same lenses on the delta.\n *\n * Bound inputs (canonical text; a skipped producer arrives as \"null\"):\n * - INPUTS_PREVIOUS / INPUTS_PRIOR_REPORT / INPUTS_PREVIOUS_PR_URL: the previous round's\n *   `round`, `prior_report` and `pr_url` ('' on the first round).\n * - INPUTS_GREEN / INPUTS_RED_CAUSE: the implementer's verdict on the checks it ran.\n * - INPUTS_PR_URL: this round's pull request.\n * - INPUTS_REVIEW_READY / INPUTS_REVIEW_ACTION: the review verdict.\n * - INPUTS_REREVIEW_*: the light review of reshape's delta, which decides in the\n *   review's place when it ran.\n * - INPUTS_REVIEW_CONTRACT_LEFT / INPUTS_REREVIEW_CONTRACT_LEFT / INPUTS_PREVIOUS_CONTRACT_LEFT:\n *   what the deciding review's contract coverage did not mark met, carried from the\n *   previous round when this round ran no review.\n * - INPUTS_CI / INPUTS_CI_RERUN: the CI agent's state, and whether it re-ran failed jobs.\n * - INPUTS_*_SUMMARY: each node's summary; the one that decided the round is reported.\n */\n\nimport { artifactsDir, emit, nullableJson, text } from '../../.shared/io.ts';\n\nconst ROUND_CAP = 4;\n\n/** Why a round ended; `round_cap` is added only when the cap stops a round that would repeat. */\ntype Ended =\n  | 'delivered'\n  | 'implement_blocked'\n  | 'review_open'\n  | 'replan'\n  | 'needs_human'\n  | 'ci_pr_caused'\n  | 'ci_other';\n\nconst previous = Number.parseInt(text(process.env.INPUTS_PREVIOUS), 10);\nconst round = (Number.isNaN(previous) ? 0 : previous) + 1;\nconst green = text(process.env.INPUTS_GREEN);\nconst redCause = text(process.env.INPUTS_RED_CAUSE);\nconst rereviewed = ['true', 'false'].includes(text(process.env.INPUTS_REREVIEW_READY));\nconst review = rereviewed ? 'REREVIEW' : 'REVIEW';\nconst reviewReady = text(process.env[`INPUTS_${review}_READY`]);\nconst reviewAction = text(process.env[`INPUTS_${review}_ACTION`]);\nconst ci = text(process.env.INPUTS_CI);\nconst ciRerun = text(process.env.INPUTS_CI_RERUN);\nconst prUrl = text(process.env.INPUTS_PR_URL);\nconst contractLeft = nullableJson(\n  rereviewed ? process.env.INPUTS_REREVIEW_CONTRACT_LEFT : process.env.INPUTS_REVIEW_CONTRACT_LEFT\n);\n\n/** The reason this round ended, and whether another round can change it. */\nfunction decide(): { reason: Ended; again: boolean } {\n  // A validation red the change did not cause still goes to review; CI judges it again.\n  const handedOff = green === 'true' || redCause === 'inherited' || redCause === 'environment';\n  if (!handedOff) return { reason: 'implement_blocked', again: false };\n  if (reviewReady !== 'true') {\n    // Neither a new plan nor evidence only a person can produce comes from another round.\n    if (reviewAction === 'replan' || reviewAction === 'needs_human') return { reason: reviewAction, again: false };\n    return { reason: 'review_open', again: true };\n  }\n  if (ci === 'green') return { reason: 'delivered', again: false };\n  if (ci === 'pr_caused') return { reason: 'ci_pr_caused', again: true };\n  return { reason: 'ci_other', again: false };\n}\n\nconst SUMMARY_OF: Record<Ended, string> = {\n  delivered: 'CI_SUMMARY',\n  implement_blocked: 'IMPLEMENT_SUMMARY',\n  review_open: `${review}_SUMMARY`,\n  replan: `${review}_SUMMARY`,\n  needs_human: `${review}_SUMMARY`,\n  ci_pr_caused: 'CI_SUMMARY',\n  ci_other: 'CI_SUMMARY',\n};\n\nconst { reason, again } = decide();\nconst capped = again && round >= ROUND_CAP;\n\nemit({\n  round,\n  done: !again || capped,\n  ready: reason === 'delivered',\n  reason: capped ? 'round_cap' : reason,\n  // A round whose implementer stopped opens no pull request; an earlier round's stands.\n  pr_url: prUrl === 'null' ? text(process.env.INPUTS_PREVIOUS_PR_URL) : prUrl,\n  // The next round's review continues from the last published report, if any.\n  // A correction for CI gets a light review: the code lens alone, on the delta.\n  light_review: reason === 'ci_pr_caused',\n  // A round whose CI agent never ran re-ran nothing.\n  ci_rerun: ciRerun === 'null' ? 'none' : ciRerun,\n  prior_report:\n    reviewReady === 'null' ? text(process.env.INPUTS_PRIOR_REPORT) : `${artifactsDir()}/review/report.md`,\n  // The latest review's open contract items; null until a review has judged coverage.\n  contract_left: contractLeft ?? nullableJson(process.env.INPUTS_PREVIOUS_CONTRACT_LEFT),\n  summary: `Round ${round}: ${capped ? `${reason} at the ${ROUND_CAP}-round cap` : reason}. ${text(process.env[`INPUTS_${SUMMARY_OF[reason]}`])}`,\n});\n","implement/scripts/assert-changed.ts":"/**\n * Deterministic guard: did this implement invocation produce work?\n *\n * An AI node that declines its task still exits 0, so without this check the stages\n * after implement would spend money or go public on nothing. It reads Archon-owned\n * facts only -- the engine's checkout observations and git objects -- never the\n * project's layout or toolchain.\n *\n * Three ways to pass, in order:\n * 1. New content: some path's content, mode, or type differs from where THIS implement\n *    invocation started. The start is the engine's own observation of the implement\n *    node's invocation, bound as `baseline`. Changes that\n *    were already in the checkout when it started are part of that start, so a dirty\n *    checkout the loop never touched does not pass. HEAD moving, staging, or an empty\n *    commit changes no content and does not pass either.\n * 2. Verified existing work: no new content, but the loop declared green AND the branch\n *    already carries commits ahead of the base branch -- a rerun that verified a fix a\n *    prior run committed is progress, not a decline.\n * 3. An honest decline on red the change did not cause: no new content, the loop is not\n *    green, and it declared that red `inherited` or `environment` with evidence in its\n *    summary. A correction round can genuinely have nothing left to edit -- the\n *    remaining break is in the base, or in configuration the run has no permission to\n *    change -- and demanding a change anyway asks for an invented one, or throws away\n *    the rounds that already landed. What such a claim is worth is the green gates'\n *    question, not this one; the tolerance lives here only so a change that cannot\n *    exist stops being required.\n *\n * Red the loop introduced still fails with nothing to show, and so does red it left\n * unexplained or unevidenced -- the same bar the green gates hold, because a cause\n * with no failing check named behind it is not a reason. A green claim with neither\n * new content nor a branch lead fails too.\n *\n * A loop that ended with its checks unfinished (`incomplete`) fails before any of\n * that is asked, whatever it changed: its work was never verified, and the green\n * gates refuse the same cause with the same message.\n *\n * Comparison: the engine records a start commit plus a manifest of only the paths that\n * differed from it, each identified by Git's blob id of its bytes (`hash-object`, clean\n * conversion applied), mode, and type. For every path that differs now or differed at\n * the start, the current identity (this node's own start observation, or the current\n * commit's tree) is compared with the starting identity (the start manifest, or the\n * start commit's tree). An observation that could not identify every path cannot prove\n * new work, and neither can a start that is not a Git checkout.\n */\n\nimport { createHash } from 'node:crypto';\nimport { readFileSync } from 'node:fs';\nimport { isAbsolute, join } from 'node:path';\nimport { artifactsDir, refuse, report, trimmed } from '../../.shared/io.ts';\nimport { PASSES_RED, passesRed, unfinishedValidation } from '../../.shared/verdict.ts';\n\n/** A git read whose failure is a broken assumption, not a state to report on. */\nfunction gitBytes(...args: string[]): Buffer {\n  const result = Bun.spawnSync(['git', '--literal-pathspecs', ...args], {\n    stdout: 'pipe',\n    stderr: 'pipe',\n  });\n  if (result.exitCode !== 0) {\n    throw new Error(`git ${args[0] ?? ''} failed: ${result.stderr.toString().trim()}`);\n  }\n  return result.stdout;\n}\n\n/** `undefined` when the ref does not resolve, which is an answer rather than a fault. */\nfunction tryGit(...args: string[]): string | undefined {\n  const result = Bun.spawnSync(['git', ...args], { stdout: 'pipe', stderr: 'pipe' });\n  return result.exitCode === 0 ? result.stdout.toString().trim() : undefined;\n}\n\n/**\n * Commits this branch carries beyond the base, or `undefined` when no base ref resolves.\n *\n * Every copy of the base counts — the local branch and the same branch on each\n * remote, whatever the remotes are named — and the fewest commits ahead wins, so a\n * stale fork's base never makes base commits look like this branch's work.\n */\nfunction commitsAheadOfBase(base: string): { readonly ref: string; readonly ahead: number } | undefined {\n  const remotes = (tryGit('for-each-ref', '--format=%(refname:short)', `refs/remotes/*/${base}`) ?? '')\n    .split('\\n')\n    .filter(ref => ref !== '');\n  let best: { readonly ref: string; readonly ahead: number } | undefined;\n  for (const ref of [...remotes, base]) {\n    const ahead = tryGit('rev-list', '--count', `${ref}..HEAD`);\n    if (ahead === undefined) continue;\n    const count = Number.parseInt(ahead, 10);\n    if (best === undefined || count < best.ahead) best = { ref, ahead: count };\n  }\n  return best;\n}\n\n// --- The engine's checkout observation, as this consumer reads it --------------------\n//\n// The owning contract is the engine's `CheckoutObservation` schema. This pack cannot\n// import engine code, so it reads only the fields it needs and rejects anything else\n// as unreadable; a conformance test in the engine feeds real observations through this\n// script so the two cannot drift silently.\n\n/** A path's identity: absent, or a kind/mode/object id. Equality is identity. */\ntype Identity = { readonly kind: 'absent' } | { readonly kind: string; readonly mode: string; readonly oid: string };\n\ninterface Observed {\n  readonly commit: string | null;\n  /** Paths that differed from `commit` when sampled, keyed by raw path bytes (base64). */\n  readonly dirty: ReadonlyMap<string, Identity>;\n}\n\ntype Reading = { readonly observed: Observed } | { readonly unknown: string };\n\nfunction isRecord(value: unknown): value is Record<string, unknown> {\n  return typeof value === 'object' && value !== null && !Array.isArray(value);\n}\n\nfunction pathKey(path: unknown): string | undefined {\n  if (typeof path === 'string') return Buffer.from(path, 'utf8').toString('base64');\n  if (isRecord(path) && typeof path.base64 === 'string') return path.base64;\n  return undefined;\n}\n\nfunction readObservation(label: string, value: unknown, runId: string): Reading {\n  if (!isRecord(value)) return { unknown: `${label} is not a checkout observation` };\n  if (value.kind === 'not_git') return { unknown: `${label} was not a Git checkout` };\n  if (value.kind === 'unavailable') {\n    return { unknown: `${label} could not be observed (${String(value.reason)})` };\n  }\n  if (value.kind !== 'git' || !isRecord(value.worktree)) {\n    return { unknown: `${label} is not a checkout observation this guard can read` };\n  }\n  const commit = value.commit;\n  if (commit !== null && typeof commit !== 'string') return { unknown: `${label} has no commit` };\n  const worktree = value.worktree;\n  if (worktree.status === 'clean') return { observed: { commit, dirty: new Map() } };\n  if (worktree.status !== 'dirty' || !isRecord(worktree.manifest)) {\n    return { unknown: `${label} has an unreadable worktree state` };\n  }\n  const pointer = worktree.manifest.pointer;\n  const digest = worktree.manifest.sha256;\n  if (!isRecord(pointer) || typeof pointer.path !== 'string' || typeof digest !== 'string') {\n    return { unknown: `${label} has no manifest reference` };\n  }\n  if (pointer.run_id !== runId) return { unknown: `${label} points at another run's manifest` };\n  if (isAbsolute(pointer.path) || pointer.path.split(/[\\\\/]/).includes('..')) {\n    return { unknown: `${label} has an unsafe manifest path` };\n  }\n  let bytes: Buffer;\n  try {\n    bytes = readFileSync(join(artifactsDir(), pointer.path));\n  } catch {\n    return { unknown: `${label}'s manifest is missing` };\n  }\n  if (createHash('sha256').update(bytes).digest('hex') !== digest) {\n    return { unknown: `${label}'s manifest does not match its recorded digest` };\n  }\n  let manifest: unknown;\n  try {\n    manifest = JSON.parse(bytes.toString('utf8'));\n  } catch {\n    return { unknown: `${label}'s manifest is not JSON` };\n  }\n  if (!isRecord(manifest) || manifest.version !== 1 || !Array.isArray(manifest.entries)) {\n    return { unknown: `${label}'s manifest has an unknown format` };\n  }\n  if (manifest.commit !== commit) return { unknown: `${label}'s manifest names another commit` };\n  const dirty = new Map<string, Identity>();\n  for (const entry of manifest.entries) {\n    if (!isRecord(entry)) return { unknown: `${label}'s manifest has a malformed entry` };\n    const key = pathKey(entry.path);\n    if (key === undefined) return { unknown: `${label}'s manifest has a malformed path` };\n    if (entry.kind === 'absent') {\n      dirty.set(key, { kind: 'absent' });\n    } else if ((entry.kind === 'file' || entry.kind === 'symlink') && typeof entry.blob === 'string') {\n      dirty.set(key, { kind: entry.kind, mode: String(entry.mode), oid: entry.blob });\n    } else if (entry.kind === 'gitlink' && typeof entry.commit === 'string') {\n      dirty.set(key, { kind: 'gitlink', mode: '160000', oid: entry.commit });\n    } else {\n      return { unknown: `${label} could not identify every changed path` };\n    }\n  }\n  return { observed: { commit, dirty } };\n}\n\n// --- Commit-side identities -----------------------------------------------------------\n\n/** NUL-separated raw records. */\nfunction splitNul(output: Buffer): Buffer[] {\n  const records: Buffer[] = [];\n  let start = 0;\n  while (start < output.length) {\n    const end = output.indexOf(0, start);\n    const stop = end === -1 ? output.length : end;\n    if (stop > start) records.push(output.subarray(start, stop));\n    start = stop + 1;\n  }\n  return records;\n}\n\n/** Paths whose tree entries differ between two commits (or every path of one). */\nfunction committedPaths(from: string | null, to: string | null): string[] {\n  if (from === to) return [];\n  let listing: Buffer;\n  if (from !== null && to !== null) {\n    listing = gitBytes('diff-tree', '-r', '-z', '--no-renames', '--name-only', from, to);\n  } else {\n    // One side is an unborn branch: every path of the other commit differs.\n    const only = from ?? to;\n    if (only === null) return [];\n    listing = gitBytes('ls-tree', '-r', '-z', '--name-only', only);\n  }\n  return splitNul(listing).map(path => path.toString('base64'));\n}\n\n/** Tree identities of the given paths in one commit; paths the tree lacks are absent. */\nfunction treeIdentities(commit: string | null, keys: readonly string[]): Map<string, Identity> {\n  const identities = new Map<string, Identity>(keys.map(key => [key, { kind: 'absent' }]));\n  if (commit === null || keys.length === 0) return identities;\n  // argv carries UTF-8 text; a non-UTF-8 path cannot be named there, so it cannot be\n  // looked up and stays absent -- the observation already refused to identify such a\n  // path as dirty, which keeps this from ever deciding equality on it.\n  const names = keys\n    .map(key => Buffer.from(key, 'base64'))\n    .filter(raw => Buffer.from(raw.toString('utf8'), 'utf8').equals(raw))\n    .map(raw => raw.toString('utf8'));\n  for (let i = 0; i < names.length; i += 200) {\n    const listing = gitBytes('ls-tree', '-r', '-z', commit, '--', ...names.slice(i, i + 200));\n    for (const record of splitNul(listing)) {\n      // \"<mode> <type> <oid>\\t<path>\"\n      const tab = record.indexOf(0x09);\n      const [mode = '', type = '', oid = ''] = record.subarray(0, tab).toString('latin1').split(' ');\n      const key = record.subarray(tab + 1).toString('base64');\n      if (!identities.has(key)) continue;\n      identities.set(key, {\n        kind: type === 'commit' ? 'gitlink' : mode === '120000' ? 'symlink' : 'file',\n        mode,\n        oid,\n      });\n    }\n  }\n  return identities;\n}\n\nfunction same(a: Identity | undefined, b: Identity | undefined): boolean {\n  if (a === undefined || b === undefined) return false;\n  if (!('oid' in a) || !('oid' in b)) return !('oid' in a) && !('oid' in b);\n  return a.kind === b.kind && a.mode === b.mode && a.oid === b.oid;\n}\n\n/** How many paths' content differs from where the invocation started. */\nfunction contentChanges(baseline: Observed, current: Observed): number {\n  const keys = new Set<string>([\n    ...baseline.dirty.keys(),\n    ...current.dirty.keys(),\n    ...committedPaths(baseline.commit, current.commit),\n  ]);\n  const all = [...keys];\n  const startTree = treeIdentities(baseline.commit, all);\n  const currentTree = treeIdentities(current.commit, all);\n  let changed = 0;\n  for (const key of all) {\n    const start = baseline.dirty.get(key) ?? startTree.get(key);\n    const now = current.dirty.get(key) ?? currentTree.get(key);\n    if (!same(now, start)) changed++;\n  }\n  return changed;\n}\n\ntype Decision = { readonly shown: string } | { readonly refusal: string };\n\nfunction decide(): Decision {\n  // The loop's verdict, bound by the workflow (`with:`): green as canonical boolean\n  // text (\"true\"/\"false\"), the declared cause of any red, and the summary that carries\n  // the evidence for it. `baseline` is the implement invocation's checkout start.\n  const green = trimmed(process.env.INPUTS_GREEN);\n  // Certified at the loop's own node: `red_cause` is an enum on its output_format,\n  // so the value here is a member or the empty string, never something to re-check.\n  const declaredCause = trimmed(process.env.INPUTS_RED_CAUSE);\n  const summary = trimmed(process.env.INPUTS_SUMMARY);\n  const baselineText = trimmed(process.env.INPUTS_BASELINE);\n  const executionText = trimmed(process.env.ARCHON_NODE_EXECUTION);\n  if (declaredCause === 'incomplete') {\n    return { refusal: unfinishedValidation('The implementation', summary) };\n  }\n\n  let unknownReason: string | undefined;\n  let execution: unknown;\n  try {\n    execution = JSON.parse(executionText);\n  } catch {\n    execution = undefined;\n  }\n  let baselineValue: unknown;\n  try {\n    baselineValue = JSON.parse(baselineText);\n  } catch {\n    baselineValue = undefined;\n  }\n  const runId = isRecord(execution) && typeof execution.runId === 'string' ? execution.runId : '';\n  const attempt = isRecord(execution) && isRecord(execution.attempt) ? execution.attempt : undefined;\n  const baseline = readObservation('the implement start', baselineValue, runId);\n  const current = readObservation('the current checkout', attempt?.checkoutStart, runId);\n  if ('unknown' in baseline) unknownReason = baseline.unknown;\n  else if ('unknown' in current) unknownReason = current.unknown;\n  else {\n    const changed = contentChanges(baseline.observed, current.observed);\n    if (changed > 0) {\n      return { shown: `${String(changed)} path(s) changed since this implement invocation started` };\n    }\n  }\n\n  const base = process.env.BASE_BRANCH ?? '';\n  if (green === 'true' && base !== '') {\n    const lead = commitsAheadOfBase(base);\n    if (lead !== undefined && lead.ahead > 0) {\n      return {\n        shown:\n          'no new changes this run; verified existing work -- ' +\n          `${lead.ahead} commit(s) ahead of ${lead.ref}`,\n      };\n    }\n  }\n\n  // Nothing to show, and nothing to do about it. The evidence bar is the green gates'\n  // own: emptiness is all that is checked, because whether the prose names a real\n  // failing check is the declaring agent's judgment and the reviewer's.\n  if (green !== 'true' && passesRed(declaredCause) && summary !== '') {\n    return {\n      shown: `no new changes this run; the remaining red is declared ${declaredCause}, not introduced`,\n    };\n  }\n\n  // A loop that stopped on a blocker it declared is not unexplained red: name it.\n  if (green !== 'true' && declaredCause === '' && summary !== '' && unknownReason === undefined) {\n    return {\n      refusal:\n        `implement declared a blocker: ${summary}\\n` +\n        'It changed no content since this invocation started, and the branch carries no ' +\n        'verified work ahead of the base.',\n    };\n  }\n\n  return {\n    refusal:\n      (unknownReason !== undefined\n        ? `implement's new work cannot be established: ${unknownReason}. `\n        : 'implement changed no content since this invocation started ' +\n          '(pre-existing uncommitted changes are part of that start), ') +\n      'and the branch carries no verified work ahead of the base ' +\n      `(green=${green || 'unknown'}, red_cause=${declaredCause || 'unknown'}).\\n` +\n      'Nothing to show is only acceptable on red the change did not cause -- declared ' +\n      `${PASSES_RED.join(' or ')}, with the failing check named in the summary. Red the ` +\n      'change introduced, red nobody explained, and a cause with no evidence behind it ' +\n      'fail here rather than reporting success.',\n  };\n}\n\nconst decision = decide();\nif ('shown' in decision) {\n  report(decision.shown);\n} else {\n  refuse(decision.refusal);\n}\n","intake/scripts/facts.ts":"/**\n * Record this run's event on its issue, claim the best waiting item, and decide what\n * it needs before any model reads its text.\n *\n * Trust is one fact read here: is the issue's author on the project's maintainer list.\n * A label request counts only when its actor, as the forge event reported it, is on\n * that list. A live run's only writes are the request and the claim. An eval run\n * writes nothing: it decides the named issue as it was at creation, as a fresh item,\n * without the queue, and hands triage only that issue's creation title and body.\n */\n\nimport type { QualifiedPr } from '../../.shared/forge.ts';\nimport { emit, refuse, text, trimmed } from '../../.shared/io.ts';\nimport { issueAtCreation, viewIssue } from '../../.shared/issue.ts';\nimport { isRequestLabel } from '../../.shared/labels.ts';\nimport {\n  bodyDigest,\n  claimNext,\n  decideIntake,\n  enqueue,\n  type IntakeRequest,\n  newWorkItem,\n  parseMode,\n  parseOrder,\n  parseTrustInput,\n  readMaintainers,\n  REQUEST_ACTIONS,\n  type RequestAction,\n  type TrustInput,\n} from '../../.shared/workitem.ts';\n\n/**\n * Decide the issue as a fresh item at creation: no stored document, no request, no\n * claim, and no labels or closed state that would give the answer away.\n */\nfunction evaluate(\n  subject: QualifiedPr,\n  maintainers: ReadonlySet<string>,\n  trustInput: TrustInput,\n  at: string,\n  runId: string\n): void {\n  const issue = viewIssue(subject);\n  const created = issueAtCreation(subject, issue);\n  const decision = decideIntake(\n    newWorkItem(subject, at),\n    { author: issue.author, labels: [], state: 'open', digest: bodyDigest(created.body) },\n    maintainers,\n    at,\n    runId,\n    trustInput\n  );\n  emit({\n    path: decision.path,\n    item: subject,\n    target: `# ${created.title}\\n\\n${created.body}`,\n    decision,\n    seen: { title: created.title, body_digest: decision.body_digest, body_from: created.body_from },\n  });\n}\n\nfunction main(): void {\n  // The inputs' own validation: a value outside their vocabularies refuses the run\n  // here, before anything is read or written.\n  const mode = parseMode(text(process.env.INPUTS_MODE));\n  const trustInput = parseTrustInput(text(process.env.INPUTS_TRUST));\n  const runId = text(process.env.WORKFLOW_ID);\n  if (runId === '')\n    throw new Error('WORKFLOW_ID is not set; the engine supplies it to every exec node');\n  const repo = {\n    host: trimmed(process.env.INPUTS_REPO_HOST),\n    path: trimmed(process.env.INPUTS_REPO_PATH),\n  };\n  const number = Number(trimmed(process.env.INPUTS_NUMBER));\n  if (repo.host === '' || repo.path === '' || !Number.isInteger(number) || number <= 0) {\n    throw new Error('repo_host, repo_path and a positive issue number are required');\n  }\n  const action = trimmed(process.env.INPUTS_ACTION) as RequestAction;\n  if (!REQUEST_ACTIONS.includes(action)) {\n    throw new Error(`action must be one of ${REQUEST_ACTIONS.join(', ')}, not \"${action}\"`);\n  }\n  const order = parseOrder(text(process.env.INPUTS_ORDER));\n  // Read before any write, so a broken list refuses the run with nothing recorded.\n  const maintainers = readMaintainers(repo);\n  const at = new Date().toISOString();\n  const subject = { repo, number };\n  const label = trimmed(process.env.INPUTS_LABEL);\n  if (mode === 'eval') {\n    evaluate(subject, maintainers, trustInput, at, runId);\n    return;\n  }\n\n  // Intake works issues. A pull request's event, or a label that asks for nothing,\n  // records no request; the run still picks up whatever waits.\n  const kind = trimmed(process.env.INPUTS_KIND);\n  if (kind === 'issue' && (action !== 'added' || isRequestLabel(label))) {\n    const request: IntakeRequest = {\n      at,\n      run_id: runId,\n      action,\n      label: action === 'added' ? label : null,\n      actor: action === 'added' ? trimmed(process.env.INPUTS_LABEL_ACTOR) || null : null,\n      // A promotion pins the body as it was when the request was recorded.\n      body_digest: action === 'added' ? bodyDigest(viewIssue(subject).body) : null,\n    };\n    enqueue(subject, request);\n  }\n\n  const doc = claimNext(order, at, runId);\n  if (doc === null) {\n    emit({ path: 'idle', item: null, target: '', decision: null, seen: null });\n    return;\n  }\n  const issue = viewIssue(doc.subject);\n  const decision = decideIntake(\n    doc,\n    { ...issue, digest: bodyDigest(issue.body) },\n    maintainers,\n    at,\n    runId,\n    trustInput\n  );\n  emit({ path: decision.path, item: doc.subject, target: issue.url, decision, seen: null });\n}\n\ntry {\n  main();\n} catch (error) {\n  refuse(`intake facts: ${error instanceof Error ? error.message : String(error)}`);\n}\n","intake/scripts/outcome.ts":"/**\n * Apply the facts node's decision: write the work item first, then the labels that\n * mirror it, then release the claim. A closed issue gets the document write only.\n * In eval mode nothing is read or written: the decision is applied to a fresh item\n * in memory and reported, with the label delta live would write, as `evaluation`.\n *\n * Bound inputs: INPUTS_PATH, INPUTS_ITEM, INPUTS_DECISION and INPUTS_SEEN from facts;\n * triage's verdict fields, each \"null\" when triage did not run; the workflow's\n * INPUTS_MODE and INPUTS_TRUST.\n */\n\nimport { parseQualifiedPr, type QualifiedPr } from '../../.shared/forge.ts';\nimport { emit, nullableJson, refuse, text, trimmed } from '../../.shared/io.ts';\nimport { viewIssue } from '../../.shared/issue.ts';\nimport {\n  type Contract,\n  type LabelVerdict,\n  isOwnedLabel,\n  type OwnedLabel,\n  type Route,\n  writeLabels,\n} from '../../.shared/labels.ts';\nimport {\n  applyDecision,\n  assertNoSelfPromotion,\n  bodyDigest,\n  type IntakeDecision,\n  mirrorLabels,\n  newWorkItem,\n  parseMode,\n  parseTrustInput,\n  type TriageResult,\n  updateClaimed,\n  type WorkItem,\n} from '../../.shared/workitem.ts';\n\n/** Triage's verdict, or null when triage did not run on this path. */\nfunction triageResult(): TriageResult | null {\n  const contract = nullableJson(process.env.INPUTS_CONTRACT) as Contract | null;\n  if (contract === null) return null;\n  const route = nullableJson(process.env.INPUTS_ROUTE) as Route;\n  const verdict: LabelVerdict = contract === 'READY' ? { contract, route } : { contract };\n  return {\n    verdict,\n    pull_request: nullableJson(process.env.INPUTS_PULL_REQUEST) as number | null,\n    type: nullableJson(process.env.INPUTS_TYPE) as TriageResult['type'],\n    size: nullableJson(process.env.INPUTS_SIZE) as TriageResult['size'],\n    complexity: nullableJson(process.env.INPUTS_COMPLEXITY) as TriageResult['complexity'],\n    importance: nullableJson(process.env.INPUTS_IMPORTANCE) as TriageResult['importance'],\n    urgency: nullableJson(process.env.INPUTS_URGENCY) as TriageResult['urgency'],\n    labels: nullableJson(process.env.INPUTS_LABELS) as string[],\n    summary: nullableJson(process.env.INPUTS_SUMMARY) as string,\n    report: nullableJson(process.env.INPUTS_REPORT) as TriageResult['report'],\n  };\n}\n\n/**\n * The labels this outcome adds and removes; null for a closed issue, whose labels are\n * left as they are.\n */\nfunction labelDelta(\n  next: WorkItem,\n  decision: IntakeDecision,\n  triage: TriageResult | null,\n  bodyMoved: boolean\n): { add: readonly string[]; remove: OwnedLabel[] } | null {\n  if (decision.path === 'closed') return null;\n  const add: readonly string[] =\n    decision.path === 'triage' && !bodyMoved && triage !== null\n      ? triage.labels\n      : mirrorLabels(next);\n  assertNoSelfPromotion(next, add);\n  // A request label added again after this run claimed its request is the next\n  // pickup's to read, when its new request already waits in next.requests.\n  const requested = new Set(next.requests.map(request => request.label));\n  return {\n    add,\n    remove: decision.labels\n      .filter(isOwnedLabel)\n      .filter(name => !add.includes(name) && !requested.has(name)),\n  };\n}\n\n/** Everything triage decided, for the eval output; null when triage did not run. */\nfunction evaluatedTriage(triage: TriageResult | null): Record<string, unknown> | null {\n  if (triage === null) return null;\n  const { verdict, ...fields } = triage;\n  return {\n    contract: verdict.contract,\n    route: nullableJson(process.env.INPUTS_ROUTE),\n    ...fields,\n    proposed_edits: nullableJson(process.env.INPUTS_PROPOSED_EDITS),\n    blocked_reason: nullableJson(process.env.INPUTS_BLOCKED_REASON),\n    blocked_by: nullableJson(process.env.INPUTS_BLOCKED_BY),\n  };\n}\n\nfunction summary(item: QualifiedPr, next: WorkItem, runId: string): string {\n  const latest = next.history.at(-1);\n  return `Issue ${String(item.number)}: ${next.stage}${latest?.run_id === runId ? `; ${latest.summary}` : ''}`;\n}\n\nfunction main(): void {\n  const mode = parseMode(text(process.env.INPUTS_MODE));\n  const path = trimmed(process.env.INPUTS_PATH);\n  if (path === 'idle') {\n    emit({\n      path,\n      item: null,\n      stage: null,\n      trust: null,\n      promoted: false,\n      labels: [],\n      summary: 'No item waits for intake.',\n      evaluation: null,\n    });\n    return;\n  }\n  const runId = text(process.env.WORKFLOW_ID);\n  if (runId === '')\n    throw new Error('WORKFLOW_ID is not set; the engine supplies it to every exec node');\n  const item = parseQualifiedPr(process.env.INPUTS_ITEM);\n  const decision = nullableJson(process.env.INPUTS_DECISION) as IntakeDecision;\n  const triage = triageResult();\n  const at = new Date().toISOString();\n\n  if (mode === 'eval') {\n    const next = applyDecision(newWorkItem(item, at), decision, triage, false, at, runId);\n    const delta = labelDelta(next, decision, triage, false) ?? { add: [], remove: [] };\n    emit({\n      path: decision.path,\n      item: item.number,\n      stage: next.stage,\n      trust: next.trust,\n      promoted: next.promoted !== null,\n      labels: [...new Set(delta.add)].sort(),\n      summary: summary(item, next, runId),\n      evaluation: {\n        trust_input: parseTrustInput(text(process.env.INPUTS_TRUST)),\n        seen: nullableJson(process.env.INPUTS_SEEN),\n        labels: delta,\n        reasons: next.history.filter(entry => entry.run_id === runId),\n        triage: evaluatedTriage(triage),\n      },\n    });\n    return;\n  }\n\n  // A promotion pins the body; an edit while triage ran leaves the verdict judging\n  // text no maintainer promoted.\n  const bodyMoved =\n    decision.path === 'triage' &&\n    decision.trust === 'outside' &&\n    bodyDigest(viewIssue(item).body) !== decision.body_digest;\n  const next = updateClaimed(item, runId, doc =>\n    applyDecision(doc, decision, triage, bodyMoved, at, runId)\n  );\n\n  const delta = labelDelta(next, decision, triage, bodyMoved);\n  const labels = delta === null ? [] : writeLabels(item, delta.add, delta.remove);\n  // Clearing the claim is what marks this run's requests honored; a run that stops\n  // before it leaves them for the next pickup to queue again.\n  updateClaimed(item, runId, doc => ({ ...doc, claim: null }));\n\n  emit({\n    path: decision.path,\n    item: item.number,\n    stage: next.stage,\n    trust: next.trust,\n    promoted: next.promoted !== null,\n    labels,\n    summary: summary(item, next, runId),\n    evaluation: null,\n  });\n}\n\ntry {\n  main();\n} catch (error) {\n  refuse(`intake outcome: ${error instanceof Error ? error.message : String(error)}`);\n}\n","investigate/scripts/verdict.ts":"/**\n * Derive the workflow's boolean outcome from the investigator's typed verdict.\n *\n * The engine's authored outcome needs a required boolean on the returns node; the\n * investigator declares one verdict (`rooted`, `refuted` or `inconclusive`). Deriving\n * `rooted` here keeps one declaration, so the two can never disagree.\n *\n * Bound inputs (`with:` bindings, canonical text in env):\n * - INPUTS_VERDICT / INPUTS_SUMMARY / INPUTS_REPORT: the investigate node's certified output.\n */\n\nimport { emit, text } from '../../.shared/io.ts';\n\nconst verdict = text(process.env.INPUTS_VERDICT);\nemit({\n  verdict,\n  rooted: verdict === 'rooted',\n  summary: text(process.env.INPUTS_SUMMARY),\n  report: JSON.parse(text(process.env.INPUTS_REPORT)) as unknown,\n});\n","pr/scripts/publish-pr.ts":"/**\n * Push the branch, then publish the pull request and record its verified identity.\n *\n * The preceding nodes judged the target and the text and proved the merged tree; this\n * node owns the two writes and proves each landed, through whichever source the run\n * selected. The push comes first and refuses on any failure (./.shared/push.ts), so a\n * pull request is never created for a head the remote does not have.\n *\n * Whether this work already has a pull request is decided here, not in a prompt: an\n * open pull request for the recorded head IS the pull request, and a second one is\n * never opened for it. A run continuing a named pull request pushes to that pull\n * request's head by merge only — the push never forces, so a head that is not an\n * ancestor of this commit refuses.\n *\n * Bound inputs (`with:` bindings, canonical text in env):\n * - INPUTS_REPO / INPUTS_HEAD_REPO: `{host, path}` of the base and head repositories.\n * - INPUTS_HEAD / INPUTS_BASE: the head and base branch names.\n * - INPUTS_EXISTING: the pull request this run continues, or `null`.\n * - INPUTS_PULL_REQUEST: the number the caller resolved for it, or empty or `null`.\n * - INPUTS_TITLE: the title.\n * - INPUTS_BODY: the certified body file.\n * - INPUTS_DRAFT: `true` opens a draft.\n */\n\nimport { unlinkSync, writeFileSync } from 'node:fs';\nimport { join } from 'node:path';\nimport { createPr, findOpenPrByHead, viewPr } from '../../.shared/pr.ts';\nimport {\n  ForgeOperationError,\n  forgeSource,\n  sameRepo,\n  type PrRecord,\n  type QualifiedPr,\n} from '../../.shared/forge.ts';\nimport { artifactsDir, emit, note, nullableJson, refuse, text, trimmed } from '../../.shared/io.ts';\nimport { pushHead } from '../../.shared/push.ts';\n\ntype Repo = QualifiedPr['repo'];\n\nfunction publish(): PrRecord {\n  const source = forgeSource();\n  const repo = JSON.parse(text(process.env.INPUTS_REPO)) as Repo;\n  const headRepo = JSON.parse(text(process.env.INPUTS_HEAD_REPO)) as Repo;\n  const head = text(process.env.INPUTS_HEAD);\n  const existing = nullableJson(process.env.INPUTS_EXISTING) as number | null;\n  const artifacts = artifactsDir();\n\n  const named = nullableJson(process.env.INPUTS_PULL_REQUEST) as number | null;\n  if (named !== null && existing !== named) {\n    throw new Error(\n      `the caller named pull request ${String(named)} to continue, but prepare declared ${String(existing ?? 'none')}`\n    );\n  }\n\n  // A continued pull request's head is checked before the push, which would\n  // otherwise land on whatever branch prepare declared.\n  if (existing !== null) {\n    const view = viewPr({ repo, number: existing }, source);\n    const observedHead = view.pr.head_repo;\n    if (view.pr.head !== head || observedHead === null || !sameRepo(observedHead, headRepo)) {\n      throw new Error(\n        `pull request ${String(existing)} has head ${String(view.pr.head_repo?.path)}:${view.pr.head}, not the recorded ${headRepo.path}:${head}`\n      );\n    }\n  }\n\n  const headRevision = pushHead({ repo, head_repo: headRepo, head });\n\n  // The run continues a named pull request: its draft state belongs to its author.\n  if (existing !== null) return viewPr({ repo, number: existing }, source).pr;\n\n  const open = findOpenPrByHead(repo, headRepo, head, source);\n  if (open) {\n    note(`publish-pr: ${open.pr.url} already has this head, so no pull request was opened.`);\n    return open.pr;\n  }\n\n  const bodyPath = text(process.env.INPUTS_BODY);\n\n  // Killing the script cannot cancel a submitted forge write. Keep this claim even\n  // after success: a retry may only reconcile it.\n  const claimPath = join(artifacts, 'pr-create-started');\n  try {\n    writeFileSync(claimPath, JSON.stringify({ repo, headRepo, head }), { flag: 'wx', mode: 0o600 });\n  } catch (error) {\n    if (error instanceof Error && 'code' in error && error.code === 'EEXIST') {\n      throw new Error(\n        `a previous PR create is unresolved; no open PR was found for ${headRepo.path}:${head}. Reconcile the write recorded at ${claimPath} before creating another PR`\n      );\n    }\n    throw error;\n  }\n  try {\n    return createPr(\n      {\n        repo,\n        headRepo,\n        head,\n        headRevision,\n        base: text(process.env.INPUTS_BASE),\n        title: text(process.env.INPUTS_TITLE),\n        bodyPath,\n        draft: trimmed(process.env.INPUTS_DRAFT) === 'true',\n      },\n      source\n    );\n  } catch (error) {\n    // A forge refusal is definite: no write was sent, so the claim would only block\n    // a retry. Every other failure may have left a pull request behind.\n    if (error instanceof ForgeOperationError && error.mutation?.outcome === 'refused') {\n      unlinkSync(claimPath);\n    }\n    throw error;\n  }\n}\n\ntry {\n  emit(publish());\n} catch (error) {\n  refuse(`publish-pr: ${error instanceof Error ? error.message : String(error)}`);\n}\n","review/scripts/prune-scratch.ts":"/**\n * Remove this run's reviewer scratch worktrees: see ../../.shared/scratch.ts.\n *\n * Bound inputs (`with:` bindings, canonical text in env):\n * - INPUTS_LENS: the one lens directory to remove, or '' for every lens's.\n */\n\nimport { artifactsDir, refuse, report, trimmed } from '../../.shared/io.ts';\nimport { pruneScratch, scratchDir } from '../../.shared/scratch.ts';\n\ntry {\n  const removed = pruneScratch(scratchDir(artifactsDir(), trimmed(process.env.INPUTS_LENS)));\n  report(`prune-scratch: removed ${String(removed.length)} scratch worktree(s)`);\n} catch (error) {\n  refuse(`prune-scratch: ${error instanceof Error ? error.message : String(error)}`);\n}\n","review/scripts/publish-review.ts":"/**\n * Publish the review report as the pull request's one canonical comment.\n *\n * The reviewer judges and writes the report; this node owns the public write, so\n * every round edits the same marked comment instead of appending another. A\n * review whose scope was a working diff has no pull request and publishes\n * nothing. The verdict passes through unchanged either way: publication is not\n * what makes a review true.\n *\n * A report goes public only about the commit its round fixed at the start\n * (review-round): the checkout must still be at it and the pull request's remote\n * head must be it. The head is checked before the scope agent's declaration, so a\n * correction that was never pushed is named as that rather than as a scope\n * mismatch. Any mismatch refuses, so a verdict about one commit can never\n * stand as the verdict on another. This node stamps that commit on the comment\n * itself rather than trusting the report's text to name it. Once published, the\n * commit is recorded beside the report as the next round's cursor.\n *\n * Bound inputs (`with:` bindings, canonical text in env):\n * - INPUTS_SCOPE: the review's requested scope. Delivery passes its verified\n *   pull-request record here, and that record is then the only write target.\n * - INPUTS_PR: the qualified pull request the scope agent declared it reviewed,\n *   or `null` for a working diff. It names the target of a standalone review.\n * - INPUTS_REPORT: path to the report this node publishes.\n * - INPUTS_HEAD: the commit this round reviewed, as review-round fixed it.\n * - INPUTS_READY / INPUTS_ACTION / INPUTS_SUMMARY / INPUTS_REPORT_POINTER /\n *   INPUTS_DISCOVERIES / INPUTS_CONTRACT_LEFT: the certified verdict fields this\n *   node forwards.\n * - INPUTS_ROUTE / INPUTS_MODE: the route agent's lens decision (\"null\" when a\n *   continuation skipped it) and review-round's output, whose lens fields hold a\n *   continuation's set. The lenses this round ran are recorded beside the report\n *   as the next round's lens set.\n */\n\nimport { mkdtempSync, readFileSync, rmSync, writeFileSync } from 'node:fs';\nimport { tmpdir } from 'node:os';\nimport { dirname, join } from 'node:path';\nimport { nodeStartCommit } from '../../.shared/checkout.ts';\nimport { upsertComment, viewPr } from '../../.shared/pr.ts';\nimport {\n  forgeSource,\n  parseQualifiedPr,\n  record,\n  sameRepo,\n  type QualifiedPr,\n} from '../../.shared/forge.ts';\nimport { emit, note, refuse, text } from '../../.shared/io.ts';\nimport { REVIEW_LENSES } from '../../.shared/review-policy.ts';\n\nconst MARKER = '<!-- archon-review-report -->';\n\n/** The pull request delivery recorded, when the scope is that JSON record. */\nfunction recordedPr(scope: string): QualifiedPr | undefined {\n  let parsed: unknown;\n  try {\n    parsed = JSON.parse(scope);\n  } catch {\n    return undefined; // a PR URL, a branch name, or empty\n  }\n  return record(parsed) ? parseQualifiedPr(scope) : undefined;\n}\n\n/** The pull request the scope agent declared, or undefined for a working diff. */\nfunction declaredPr(value: string): QualifiedPr | undefined {\n  const target = value.trim() || 'null';\n  const parsed: unknown = JSON.parse(target);\n  // Older persisted scope output used `{}` for a working diff.\n  if (parsed === null || (typeof parsed === 'object' && Object.keys(parsed).length === 0)) {\n    return undefined;\n  }\n  return parseQualifiedPr(target);\n}\n\n/** The lenses this round ran: the route agent's call on a first round, review-round's otherwise. */\nfunction lenses(): Record<string, boolean> {\n  const decision = record(JSON.parse(text(process.env.INPUTS_ROUTE) || 'null'));\n  const source = decision ?? record(JSON.parse(text(process.env.INPUTS_MODE)));\n  return Object.fromEntries(REVIEW_LENSES.map(lens => [lens, source?.[lens] === true]));\n}\n\nfunction label(pr: QualifiedPr | undefined): string {\n  return pr ? `${pr.repo.host}/${pr.repo.path}#${String(pr.number)}` : 'no pull request';\n}\n\ntry {\n  const source = forgeSource();\n  const verdict = {\n    ready: JSON.parse(text(process.env.INPUTS_READY)) as boolean,\n    action: text(process.env.INPUTS_ACTION),\n    findings_summary: text(process.env.INPUTS_SUMMARY),\n    report: JSON.parse(text(process.env.INPUTS_REPORT_POINTER)) as unknown,\n    discoveries: JSON.parse(text(process.env.INPUTS_DISCOVERIES)) as unknown,\n    contract_left: JSON.parse(text(process.env.INPUTS_CONTRACT_LEFT)) as unknown,\n  };\n  const recorded = recordedPr(text(process.env.INPUTS_SCOPE));\n  const declared = declaredPr(text(process.env.INPUTS_PR));\n  const pr = recorded ?? declared;\n  const head = text(process.env.INPUTS_HEAD).trim();\n  const reportPath = text(process.env.INPUTS_REPORT);\n  const report = readFileSync(reportPath, 'utf8');\n  if (report.trim() === '') throw new Error('the review report is empty');\n  const checkout = nodeStartCommit();\n  if (checkout !== head) {\n    throw new Error(`this round reviewed ${head}, but the checkout is now at ${checkout}`);\n  }\n  if (pr) {\n    const remote = viewPr(pr, source).pr.head_revision;\n    if (remote !== head) {\n      throw new Error(\n        `this round reviewed ${head}, but ${label(pr)} is at ${remote ?? 'an unknown head'}: the commits under review were not pushed`\n      );\n    }\n  }\n  if (\n    recorded &&\n    (declared?.number !== recorded.number || !sameRepo(declared.repo, recorded.repo))\n  ) {\n    throw new Error(\n      `the review scope declared ${label(declared)}, but delivery recorded ${label(recorded)}`\n    );\n  }\n  if (!pr) {\n    note('publish-review: the review scope is a working diff, so no comment was published.');\n  } else {\n    const directory = mkdtempSync(join(tmpdir(), 'archon-review-'));\n    try {\n      const marked = join(directory, 'comment.md');\n      writeFileSync(marked, `${MARKER}\\nReviewed commit: \\`${head}\\`\\n\\n${report}`);\n      const comment = upsertComment(pr, MARKER, marked, source);\n      note(`publish-review: canonical review comment at ${comment.url}`);\n    } finally {\n      rmSync(directory, { recursive: true, force: true });\n    }\n  }\n  // review-round reads these as the next round's cursor and lens set.\n  writeFileSync(join(dirname(reportPath), 'reviewed-head'), `${head}\\n`);\n  writeFileSync(join(dirname(reportPath), 'reviewed-lenses.json'), JSON.stringify(lenses()));\n  emit(verdict);\n} catch (error) {\n  refuse(`publish-review: ${error instanceof Error ? error.message : String(error)}`);\n}\n","review/scripts/review-round.ts":"/**\n * Fix what this review round reviews: the mode, the commit, and the cursor.\n *\n * The reviewed commit is the checkout's HEAD when the round starts, as the engine\n * observed it. Nothing an agent reads chooses it: a recorded pull request's\n * `head_revision` is captured when the PR opens and goes stale with every later\n * push, so a round that trusted it would review an older commit than the one the\n * PR carries. publish-review checks the same commit against the checkout and the\n * PR's remote head before the verdict goes public, then records it beside the\n * report as the next round's cursor.\n *\n * A continuation round's cursor is that recorded commit. The head must descend\n * from it: a head that is the cursor's ancestor, or off its history, would make\n * the delta run backwards or cover commits the previous round never read, so the\n * round refuses instead.\n *\n * A first round's lenses are the route agent's call. A continuation reruns the\n * lenses the previous round ran, which publish-review recorded beside the report,\n * on the delta only. A light continuation, which follows a correction for CI\n * rather than for review, runs the general code lens alone.\n *\n * The prior report is a declared input an outside caller can fill with a path\n * from an earlier run, so its existence is checked here too: a continuation that\n * cannot read the report it continues from would review nothing and say it\n * reviewed everything.\n *\n * The part assignment passes through unchanged: the node's `output_format` owns\n * its shape, so the engine refuses a malformed one before any agent reads it.\n *\n * Bound inputs (`with:` bindings, canonical text in env):\n * - INPUTS_PRIOR_REPORT: the previous round's report path, or empty for round one.\n * - INPUTS_LIGHT: \"true\" when this continuation follows a CI correction.\n * - INPUTS_PART: the run's part assignment as JSON, or empty for the whole contract.\n */\n\nimport { existsSync, readFileSync, statSync } from 'node:fs';\nimport { dirname, join } from 'node:path';\nimport { nodeStartCommit } from '../../.shared/checkout.ts';\nimport { FULL_REVIEW_RISKS, REVIEW_LENSES, type ReviewLens } from '../../.shared/review-policy.ts';\nimport { emit, nullableJson, refuse, trimmed } from '../../.shared/io.ts';\n\n/**\n * The bound part assignment. The refusal drops the parser's message, which quotes\n * a token of the operator's text.\n */\nfunction partAssignment(value: string | undefined): unknown {\n  try {\n    return nullableJson(value);\n  } catch {\n    throw new Error('the part input is not JSON');\n  }\n}\n\n/** Where publish-review records the commit a published report reviewed. */\nconst REVIEWED_HEAD = 'reviewed-head';\n/** Where publish-review records the lenses that round ran. */\nconst REVIEWED_LENSES = 'reviewed-lenses.json';\ntype Lenses = Record<ReviewLens, boolean>;\nconst NO_LENSES: Lenses = { seams: false, code: false, tests: false, errors: false, docs: false };\n\n/** The lens set publish-review recorded, refused unless it names every lens as a boolean. */\nfunction recordedLenses(path: string): Lenses {\n  if (!existsSync(path)) {\n    throw new Error(`the previous review report records no lenses (${path} is missing)`);\n  }\n  const value: unknown = JSON.parse(readFileSync(path, 'utf8'));\n  const lenses = { ...NO_LENSES };\n  for (const lens of REVIEW_LENSES) {\n    const ran: unknown = (value as Record<string, unknown> | null)?.[lens];\n    if (typeof ran !== 'boolean') throw new Error(`${path} does not record lens '${lens}'`);\n    lenses[lens] = ran;\n  }\n  return lenses;\n}\n\nfunction isFile(path: string): boolean {\n  try {\n    return statSync(path).isFile();\n  } catch {\n    return false;\n  }\n}\n\nfunction descends(head: string, cursor: string): boolean {\n  const result = Bun.spawnSync(['git', 'merge-base', '--is-ancestor', cursor, head]);\n  if (result.exitCode === 0) return true;\n  if (result.exitCode === 1) return false;\n  throw new Error(\n    `could not compare ${head} with the previous round's reviewed commit ${cursor}: ${result.stderr.toString().trim()}`\n  );\n}\n\ntry {\n  const part = partAssignment(process.env.INPUTS_PART);\n  const prior = trimmed(process.env.INPUTS_PRIOR_REPORT);\n  const head = nodeStartCommit();\n  // The engine's identity for this node, which synthesis uses to count only this\n  // round's lens artifacts.\n  const execution: unknown = JSON.parse(process.env.ARCHON_NODE_EXECUTION ?? '');\n  if (prior === '') {\n    emit({ continuation: false, head, cursor: '', risks: FULL_REVIEW_RISKS, execution, ...NO_LENSES, part });\n  } else {\n    if (!isFile(prior)) throw new Error(`the previous review report does not exist: ${prior}`);\n    const recorded = join(dirname(prior), REVIEWED_HEAD);\n    if (!existsSync(recorded)) {\n      throw new Error(\n        `the previous review report records no reviewed commit (${recorded} is missing)`\n      );\n    }\n    const cursor = readFileSync(recorded, 'utf8').trim();\n    if (!descends(head, cursor)) {\n      throw new Error(\n        `the checkout is at ${head}, which does not descend from ${cursor}, the commit the previous round reviewed; reviewing it would diff backwards or skip commits`\n      );\n    }\n    const lenses =\n      trimmed(process.env.INPUTS_LIGHT) === 'true'\n        ? { ...NO_LENSES, code: true }\n        : recordedLenses(join(dirname(prior), REVIEWED_LENSES));\n    emit({ continuation: true, head, cursor, risks: FULL_REVIEW_RISKS, execution, ...lenses, part });\n  }\n} catch (error) {\n  refuse(`review-round: ${error instanceof Error ? error.message : String(error)}`);\n}\n","ship/scripts/outcome.ts":"/**\n * The result of every legitimate ending of the routed fix chain, which the `report`\n * node relays as the workflow's return.\n *\n * Delivery is accepted when the deliver branch ran and reported its pull request\n * ready; a delivery that ended not ready reports deliver's own reason. Every other\n * completion reports, in the producing node's\n * own words, why nothing was delivered — and says plainly when requested work was\n * not done, so a completed run that shipped nothing never reads as a success it is\n * not. `delivered` is this workflow's authored outcome: an honest \"no work is owed\"\n * is a successful run that shipped nothing, and the two facts are separate.\n *\n * Bound inputs (`with:` bindings, canonical text in env):\n * - INPUTS_ROUTE / INPUTS_CONTRACT / INPUTS_BLOCKED_REASON / INPUTS_SUMMARY:\n *   triage's verdict.\n * - INPUTS_INV_VERDICT / INPUTS_INV_SUMMARY: the investigation's verdict and\n *   summary, or \"null\" when it did not run.\n * - INPUTS_PLAN_SUMMARY / INPUTS_OPEN_QUESTIONS: the planner's summary and the calls it\n *   left to a person, or \"null\" when it did not run.\n * - INPUTS_DELIVERED / INPUTS_DELIVERY / INPUTS_DELIVERY_REASON / INPUTS_PR_URL:\n *   deliver's `ready`, `summary`, `reason` and `pr_url`, or \"null\" when the deliver\n *   branch was skipped.\n *\n * A failed delivery arrives as deliver's `ready: false, reason: failed` report and is\n * relayed like any other not-ready delivery. A failure before delivery skips this\n * node; the workflow's `report` node answers then.\n */\n\nimport { artifactsDir, emit, text } from '../../.shared/io.ts';\nimport { caveats } from '../../.shared/report.ts';\n\nconst artifacts = artifactsDir();\nconst listingFile = process.env.TYPED_ARTIFACTS_FILE;\nconst route = text(process.env.INPUTS_ROUTE);\nconst contract = text(process.env.INPUTS_CONTRACT);\nconst blockedReason = text(process.env.INPUTS_BLOCKED_REASON);\nconst summary = text(process.env.INPUTS_SUMMARY);\n/** A string binding with `if_skipped: null`: the producer's text, or null when it was skipped. */\nfunction optional(value: string | undefined): string | null {\n  const bound = text(value);\n  return bound === 'null' ? null : bound;\n}\n\nconst invVerdict = optional(process.env.INPUTS_INV_VERDICT);\nconst invSummary = optional(process.env.INPUTS_INV_SUMMARY);\nconst planSummary = optional(process.env.INPUTS_PLAN_SUMMARY);\nconst openQuestions = JSON.parse(text(process.env.INPUTS_OPEN_QUESTIONS) || 'null') as\n  | string[]\n  | null;\nconst delivered = text(process.env.INPUTS_DELIVERED) || 'null';\nconst delivery = text(process.env.INPUTS_DELIVERY);\n\n/** Why no delivery ran. */\ntype Stop = 'no_action' | 'blocked' | 'needs_contract' | 'refuted' | 'not_rooted' | 'needs_human';\n\n/**\n * The planner's open questions as a list. Each carries the direction line that would\n * settle it next time; the operator decides whether to record it.\n */\nfunction questions(): string {\n  return (openQuestions ?? []).map(question => `- ${question}`).join('\\n');\n}\n\nfunction stopped(): { readonly reason: Stop; readonly text: string; readonly report: string } {\n  if (route === 'no_action') {\n    if (contract === 'NO_ACTION') {\n      return { reason: 'no_action', text: `No delivery needed: ${summary}`, report: 'triage.md' };\n    }\n    if (contract === 'BLOCKED') {\n      return { reason: 'blocked', text: `Not done: blocked on ${blockedReason}. ${summary}`, report: 'triage.md' };\n    }\n    return {\n      reason: 'needs_contract',\n      text: `Not done: the work item needs contract work before a run can start. ${summary}`,\n      report: 'triage.md',\n    };\n  }\n  if (route === 'investigate') {\n    if (invVerdict === 'refuted') {\n      return {\n        reason: 'refuted',\n        text: `No work owed in this repository: ${invSummary ?? ''}`,\n        report: 'investigation.md',\n      };\n    }\n    return {\n      reason: 'not_rooted',\n      text: `Not done: the investigation was inconclusive. ${invSummary ?? ''}`,\n      report: 'investigation.md',\n    };\n  }\n  return {\n    reason: 'needs_human',\n    text: `Not done: planning stopped on calls only a person can make. ${planSummary ?? ''}\\n${questions() || '- The planner named no question; read the plan.'}`,\n    report: 'plan.md',\n  };\n}\n\nif (delivered === 'null') {\n  const stop = stopped();\n  emit({\n    delivered: false,\n    reason: stop.reason,\n    pr_url: '',\n    summary: `${stop.text.trim()}\\nReport: ${artifacts}/${stop.report}` + caveats(artifacts, { listingFile }),\n  });\n} else {\n  // Deliver ran, so its outcome is the report; its summary already carries the caveats.\n  // Questions the planner judged non-blocking still reach the operator.\n  const open = questions();\n  emit({\n    delivered: delivered === 'true',\n    reason: text(process.env.INPUTS_DELIVERY_REASON),\n    pr_url: text(process.env.INPUTS_PR_URL),\n    summary: open === '' ? delivery : `${delivery}\\n\\nOpen questions the planner judged non-blocking:\\n${open}`,\n  });\n}\n","ship/scripts/report.ts":"/**\n * The ship tail's terminal report on every ending, a node failure included.\n *\n * When the outcome node ran, its report passes through unchanged; a failed delivery\n * reaches it as deliver's own `failed` report. When a node failure before delivery,\n * such as a planner or investigator crash, kept it from running, the report is not\n * delivered with reason `failed`; the run still fails, and its terminal record names\n * the node that failed.\n *\n * Bound inputs (`with:` bindings, canonical text in env):\n * - INPUTS_OUTCOME: the outcome node's report, or \"null\" when a node failure kept it\n *   from running.\n */\n\nimport { artifactsDir, emit, nullableJson } from '../../.shared/io.ts';\nimport { failed } from '../../.shared/report.ts';\n\nconst outcome = nullableJson(process.env.INPUTS_OUTCOME);\nemit(\n  outcome ?? {\n    delivered: false,\n    reason: 'failed',\n    pr_url: '',\n    summary: failed(artifactsDir(), { listingFile: process.env.TYPED_ARTIFACTS_FILE }),\n  }\n);\n","simplify/scripts/prune-scratch.ts":"/**\n * Remove this run's reviewer scratch worktrees: see ../../.shared/scratch.ts.\n *\n * Bound inputs (`with:` bindings, canonical text in env):\n * - INPUTS_LENS: the one lens directory to remove, or '' for every lens's.\n */\n\nimport { artifactsDir, refuse, report, trimmed } from '../../.shared/io.ts';\nimport { pruneScratch, scratchDir } from '../../.shared/scratch.ts';\n\ntry {\n  const removed = pruneScratch(scratchDir(artifactsDir(), trimmed(process.env.INPUTS_LENS)));\n  report(`prune-scratch: removed ${String(removed.length)} scratch worktree(s)`);\n} catch (error) {\n  refuse(`prune-scratch: ${error instanceof Error ? error.message : String(error)}`);\n}\n","triage/scripts/policy.ts":"/**\n * Hand the triage prompt the directory holding the pack's default policy documents.\n *\n * A run captures the pack's source before it starts, from a binary's embedded bundle\n * as from a source checkout, and runs this script from that capture, so the defaults\n * are found from this file's own location rather than from any path the engine knows.\n * The agent chooses between the project's document and the default; no code opens either.\n */\n\nimport { join } from 'node:path';\nimport { emit } from '../../.shared/io.ts';\n\nemit({ defaults: join(import.meta.dir, '../../.shared/policy') });\n","triage/scripts/verdict.ts":"/**\n * Validate the triage verdict before it routes work, and apply its labels.\n *\n * The prompt judges; the triage node's schema admits only legal decisions (one\n * branch per contract verdict, each carrying only its own fields), so an illegal\n * combination is re-asked at that node rather than refused here. This flattens the\n * decision into the fields every caller reads and checks what a schema cannot:\n * blockers are qualified URLs. The pack's own labels\n * derive from the declared fields here rather than being chosen by the model, and\n * only when the run was launched with publish=true and the target is a tracker\n * issue does this verify the item's identity on the tracker, apply the labels, and\n * read them back. Area labels are never created: the prompt may only pick labels\n * the repository already has. Publishing uses the selected forge source.\n */\n\nimport { record, type QualifiedPr } from '../../.shared/forge.ts';\nimport { emit, refuse, text, trimmed } from '../../.shared/io.ts';\nimport {\n  type Contract,\n  isOwnedLabel,\n  OWNED_LABEL_NAMES,\n  type Route,\n  type Size,\n  type WorkType,\n  wantedLabels,\n  writeLabels,\n} from '../../.shared/labels.ts';\n\ntype Item = QualifiedPr;\n/** One of triage's judged fields: a value and the one-line reason for it. */\ninterface Field<Value extends string> {\n  readonly value: Value;\n  readonly reason: string;\n}\ninterface Edits {\n  readonly title: string;\n  readonly body: string;\n}\n\n/** A `from:` binding arrives as the producer's JSON, already certified against its schema. */\nfunction bound(value: string | undefined): unknown {\n  return JSON.parse(text(value));\n}\n\nfunction isQualifiedUrl(value: string): boolean {\n  if (value === '' || /\\s/.test(value)) return false;\n  try {\n    const url = new URL(value);\n    return (url.protocol === 'http:' || url.protocol === 'https:') && url.hostname !== '';\n  } catch {\n    return false;\n  }\n}\n\n/** One branch of the triage decision, as the node's schema admits it. */\ntype Decision =\n  | { contract: 'READY'; route: Exclude<Route, 'continue'> }\n  | { contract: 'READY'; route: 'continue'; pull_request: number }\n  | { contract: 'NEEDS_CONTRACT_WORK'; proposed_edits: Edits }\n  | { contract: 'BLOCKED'; blocked_reason: string; blocked_by: string[] }\n  | { contract: 'NO_ACTION' };\n\nfunction main(): void {\n  const decision = bound(process.env.INPUTS_DECISION) as Decision;\n  const contract: Contract = decision.contract;\n  const route = 'route' in decision ? decision.route : 'no_action';\n  const edits: Edits = 'proposed_edits' in decision ? decision.proposed_edits : { title: '', body: '' };\n  const blockedReason = 'blocked_reason' in decision ? decision.blocked_reason : '';\n  const blockedBy = 'blocked_by' in decision ? decision.blocked_by : [];\n  const pullRequest = 'pull_request' in decision ? decision.pull_request : null;\n  const type = bound(process.env.INPUTS_TYPE) as Field<WorkType>;\n  const size = bound(process.env.INPUTS_SIZE) as Field<Size>;\n  // Passed through for the caller; no label mirrors these three.\n  const complexity = bound(process.env.INPUTS_COMPLEXITY) as Field<string>;\n  const importance = bound(process.env.INPUTS_IMPORTANCE) as Field<string>;\n  const urgency = bound(process.env.INPUTS_URGENCY) as Field<string>;\n  const publish = text(process.env.INPUTS_PUBLISH) === 'true';\n  const summary = text(process.env.INPUTS_SUMMARY);\n  const area = bound(process.env.INPUTS_AREA_LABELS) as string[];\n  const boundItem = record(bound(process.env.INPUTS_ITEM));\n  const repo = record(boundItem?.repo);\n  if (\n    typeof repo?.host !== 'string' ||\n    typeof repo.path !== 'string' ||\n    typeof boundItem?.number !== 'number' ||\n    !Number.isInteger(boundItem.number) ||\n    !(\n      (repo.host === '' && repo.path === '' && boundItem.number === 0) ||\n      (repo.host.trim() !== '' && repo.path.trim() !== '' && boundItem.number > 0)\n    )\n  ) {\n    refuse(\n      'invalid triage verdict: item requires a qualified repo and positive number, or the empty repo and zero sentinel'\n    );\n    return;\n  }\n  const item: Item | undefined =\n    boundItem.number === 0\n      ? undefined\n      : { repo: { host: repo.host, path: repo.path }, number: boundItem.number };\n  const report = bound(process.env.INPUTS_REPORT);\n\n  const invalid = (message: string): void => {\n    refuse(`invalid triage verdict: ${message}`);\n  };\n\n  if (!blockedBy.every(isQualifiedUrl)) {\n    invalid('blocked_by must be a list of fully qualified http(s) URLs');\n    return;\n  }\n  if (trimmed(summary) === '') {\n    invalid('summary is empty');\n    return;\n  }\n  if (area.some(name => name === '')) {\n    invalid('area_labels must be label names');\n    return;\n  }\n  if (area.some(isOwnedLabel)) {\n    // The state, type and size labels are derived below; a pack label smuggled in\n    // as an area label would be added beside the derived ones or removed as stale.\n    invalid('area_labels may not name a pack label; those derive from the verdict');\n    return;\n  }\n\n  const wanted = wantedLabels(decision, type.value, size.value);\n\n  const published = publish && item !== undefined;\n  const labels = published\n    ? writeLabels(\n        item,\n        [...wanted, ...area],\n        OWNED_LABEL_NAMES.filter(name => !wanted.some(label => label === name))\n      )\n    : [...new Set([...wanted, ...area])].sort();\n\n  emit({\n    contract,\n    route,\n    pull_request: pullRequest,\n    ready: contract === 'READY',\n    type,\n    size,\n    complexity,\n    importance,\n    urgency,\n    labels,\n    published,\n    proposed_edits: { title: edits.title, body: edits.body },\n    blocked_reason: blockedReason,\n    blocked_by: blockedBy,\n    summary,\n    report,\n  });\n}\n\ntry {\n  main();\n} catch (error) {\n  refuse(`triage labels: ${error instanceof Error ? error.message : String(error)}`);\n}\n","upkeep/scripts/outcome.ts":"/**\n * One return for every legitimate terminal result of the upkeep chain.\n *\n * A no_action assessment completes with the report that explains it; an update is\n * delivered when the deliver branch ran and reported its pull request ready, and\n * otherwise reports deliver's own reason. `delivered` is this workflow's authored\n * outcome: the run succeeded either way, and whether an update shipped is a\n * separate fact.\n *\n * Bound inputs (`with:` bindings, canonical text in env):\n * - INPUTS_ACTION / INPUTS_SUMMARY: the assessment's verdict.\n * - INPUTS_DELIVERED / INPUTS_DELIVERY / INPUTS_PR_URL: deliver's `ready`, `summary`\n *   and `pr_url`, or \"null\" when the deliver branch was skipped (no_action).\n *\n * A failed delivery arrives as deliver's not-ready report, its summary saying a node\n * failed, and is relayed like any other not-ready delivery; the run still fails,\n * naming the node that failed.\n */\n\nimport { artifactsDir, emit, text } from '../../.shared/io.ts';\nimport { caveats } from '../../.shared/report.ts';\n\nconst artifacts = artifactsDir();\nconst listingFile = process.env.TYPED_ARTIFACTS_FILE;\nconst action = text(process.env.INPUTS_ACTION);\nconst summary = text(process.env.INPUTS_SUMMARY);\n\nif (action === 'no_action') {\n  emit({\n    delivered: false,\n    pr_url: '',\n    summary:\n      `No update needed: ${summary}\\nReport: ${artifacts}/upkeep-assessment.md` +\n      caveats(artifacts, { listingFile }),\n  });\n} else {\n  // Deliver ran, so its outcome is the report; its summary already carries the caveats.\n  emit({\n    delivered: text(process.env.INPUTS_DELIVERED) === 'true',\n    pr_url: text(process.env.INPUTS_PR_URL),\n    summary: text(process.env.INPUTS_DELIVERY),\n  });\n}\n","validate/scripts/compare.ts":"import { relative } from 'node:path';\nimport { compareComposition, readComparisonRequest } from '../../.shared/composition.ts';\nimport { artifactsDir, emit, trimmed } from '../../.shared/io.ts';\n\nconst request = readComparisonRequest(trimmed(process.env.INPUTS_COMPARISON));\nconst runId = process.env.WORKFLOW_ID;\nif (!runId) throw new Error('WORKFLOW_ID is required for composition artifact attribution.');\nconst artifacts = artifactsDir();\nconst result = await compareComposition(process.cwd(), artifacts, request);\nemit({\n  ...result.verdict,\n  evidence: {\n    type: 'archon_artifact',\n    run_id: runId,\n    path: relative(artifacts, result.path).split('\\\\').join('/'),\n  },\n});\n","validate/scripts/mode.ts":"import { emit } from '../../.shared/io.ts';\n\nconst comparison = process.env.INPUTS_COMPARISON ?? '';\nif (comparison !== '' && comparison.trim() === '') {\n  throw new Error('Comparison path must not contain only whitespace.');\n}\nemit({ comparison: comparison !== '' });\n","validate/scripts/result.ts":"import { emit, text } from '../../.shared/io.ts';\n\n// Each producer is certified by its node's schema. The comparison path and the\n// ordinary path are exclusive; on the ordinary path, `run` is null only when its\n// timeout stopped the gate, and `classify` ran exactly when `run` reported red.\nconst comparison: unknown = JSON.parse(text(process.env.INPUTS_COMPARISON));\nconst run = JSON.parse(text(process.env.INPUTS_RUN)) as {\n  status: 'green' | 'red' | 'incomplete';\n  summary: string;\n} | null;\nconst classification = JSON.parse(text(process.env.INPUTS_CLASSIFICATION)) as {\n  red_cause: 'introduced' | 'inherited' | 'environment';\n  summary: string;\n} | null;\n\nif (comparison !== null) {\n  if (run !== null || classification !== null) {\n    throw new Error('Validation requires exactly one executed path.');\n  }\n  emit(comparison);\n} else if (run === null) {\n  emit({\n    green: false,\n    red_cause: 'incomplete',\n    summary:\n      \"The project gate didn't finish: the check runner's time limit stopped it. \" +\n      'validation.md records which checks ran and which never did.',\n    evidence: null,\n  });\n} else if (run.status === 'red') {\n  if (classification === null) throw new Error('A red gate reached the result unclassified.');\n  emit({\n    green: false,\n    red_cause: classification.red_cause,\n    summary: classification.summary,\n    evidence: null,\n  });\n} else {\n  emit({\n    green: run.status === 'green',\n    red_cause: run.status === 'green' ? '' : 'incomplete',\n    summary: run.summary,\n    evidence: null,\n  });\n}\n","validate/scripts/run-checks.ts":"/**\n * Runs the checks `discover` declared, in order, and records what happened.\n *\n * Every exit status lands in `$ARTIFACTS_DIR/validation.md`, rewritten after each\n * check so the record is current if the node is stopped. Each check's full output\n * goes to its own log under `$ARTIFACTS_DIR/validation/`. Checks belong to groups\n * the discovering agent declared: independent gates are separate groups. Within a\n * group the first failing check ends that group — later ones are recorded as never\n * run, which is how a project's own aggregate gate behaves — but every group runs,\n * so one gate's failure never hides another's result. A project with one gate has\n * one group and behaves exactly as a single ordered chain.\n *\n * The status is read from exit statuses alone:\n * - `red`: every check that should run did, and one exited non-zero or was killed by\n *   a signal it did not get from this script. `classify` judges why.\n * - `incomplete`: a check could not be started, so part of the gate never ran; any\n *   check that did fail is named in the summary.\n * - `green`: every declared check ran and exited 0. No declared checks is green only\n *   because `discover` judged that the project defines none; its notes say so.\n *\n * No timer lives here. The node's `timeout:` is the only one, and the engine stops\n * this script with SIGTERM when it expires. The handler below then stops the\n * running check's whole process tree, records the stop, and re-raises the signal\n * so the engine sees a timeout rather than a result.\n */\n\nimport { spawn, type ChildProcess } from 'node:child_process';\nimport { closeSync, existsSync, mkdirSync, openSync, readFileSync, writeFileSync } from 'node:fs';\nimport { join } from 'node:path';\nimport { artifactsDir, emit, text } from '../../.shared/io.ts';\nimport { projectEnvironment } from '../../.shared/node-env.ts';\n\ninterface Check {\n  name: string;\n  argv: string[];\n  group: string;\n}\n\nexport interface Discovery {\n  checks: Check[];\n  notes: string;\n}\n\ntype Outcome =\n  | { kind: 'passed' }\n  | { kind: 'failed'; exitCode: number | null; signal: string | null }\n  | { kind: 'not-started'; error: string }\n  | { kind: 'stopped'; signal: string }\n  | { kind: 'running' }\n  | { kind: 'never-ran' };\n\ninterface Entry {\n  check: Check;\n  log: string;\n  outcome: Outcome;\n  seconds: number | null;\n}\n\n// `discover`'s output is certified against its node's schema before it is bound here.\nconst discovery = JSON.parse(text(process.env.INPUTS_DISCOVERY)) as Discovery;\nconst cwd = process.cwd();\nconst artifacts = artifactsDir();\nconst logDir = join(artifacts, 'validation');\nconst report = join(artifacts, 'validation.md');\n// The checks run as the project's own gate, not as part of this run.\nconst gateEnv = projectEnvironment(process.env);\n\nconst TAIL_LINES = 60;\n\nfunction describe(outcome: Outcome): string {\n  switch (outcome.kind) {\n    case 'passed':\n      return 'passed (exit 0)';\n    case 'failed':\n      return outcome.signal === null\n        ? `failed (exit ${String(outcome.exitCode)})`\n        : `failed (killed by ${outcome.signal})`;\n    case 'not-started':\n      return `could not start: ${outcome.error}`;\n    case 'stopped':\n      return `did not finish: the node's time limit stopped it (${outcome.signal})`;\n    case 'running':\n      return 'running';\n    case 'never-ran':\n      return 'never ran';\n  }\n}\n\nfunction tail(path: string): string {\n  if (!existsSync(path)) return '';\n  const lines = readFileSync(path, 'utf8').trimEnd().split('\\n');\n  return lines.slice(-TAIL_LINES).join('\\n');\n}\n\nfunction render(entries: readonly Entry[]): void {\n  const groups = new Set(entries.map(entry => entry.check.group)).size;\n  const lines = ['# Validation', ''];\n  if (discovery.notes.trim() !== '') lines.push(discovery.notes.trim(), '');\n  if (entries.length === 0) lines.push('The project defines no checks, so none ran.', '');\n  for (const [index, entry] of entries.entries()) {\n    const seconds = entry.seconds === null ? '' : ` after ${entry.seconds.toFixed(0)}s`;\n    const group = groups > 1 ? ` (group: ${entry.check.group})` : '';\n    lines.push(`## ${String(index + 1)}. ${entry.check.name}${group}`, '');\n    lines.push(`\\`${entry.check.argv.join(' ')}\\` ${describe(entry.outcome)}${seconds}.`);\n    const kind = entry.outcome.kind;\n    if (kind === 'failed' || kind === 'stopped' || kind === 'not-started') {\n      const output = tail(entry.log);\n      if (output !== '') {\n        lines.push('', `Last ${String(TAIL_LINES)} lines of output:`, '', '```', output, '```');\n      }\n    }\n    if (kind !== 'never-ran' && kind !== 'not-started')\n      lines.push('', `Full output: \\`${entry.log}\\``);\n    lines.push('');\n  }\n  writeFileSync(report, `${lines.join('\\n').trimEnd()}\\n`);\n}\n\nconst entries: Entry[] = discovery.checks.map((check, index) => ({\n  check,\n  log: join(logDir, `${String(index + 1)}.log`),\n  outcome: { kind: 'never-ran' },\n  seconds: null,\n}));\nlet current: { entry: Entry; child: ChildProcess; started: number } | null = null;\n\n// POSIX only: a detached child leads its own process group, so one signal reaches\n// every process the check started. Windows has no process groups, and the engine\n// ends a timed-out script there without a signal this handler could catch.\nconst ownGroup = process.platform !== 'win32';\n\nfunction stopCurrent(signal: NodeJS.Signals): void {\n  if (current === null) return;\n  const { entry, child, started } = current;\n  entry.outcome = { kind: 'stopped', signal };\n  entry.seconds = (Date.now() - started) / 1000;\n  if (child.pid === undefined) return;\n  try {\n    if (ownGroup) process.kill(-child.pid, 'SIGKILL');\n    else child.kill('SIGKILL');\n  } catch {\n    // The group already exited between its last output and this signal.\n  }\n}\n\nfunction onSignal(signal: NodeJS.Signals): void {\n  stopCurrent(signal);\n  render(entries);\n  // Re-raise with default handling, so the engine sees the node stopped by its\n  // signal. Exiting normally here would read to the engine as a finished run.\n  process.removeAllListeners(signal);\n  process.kill(process.pid, signal);\n}\nprocess.on('SIGTERM', onSignal);\nprocess.on('SIGINT', onSignal);\n\nfunction runOne(entry: Entry): Promise<void> {\n  const fd = openSync(entry.log, 'w');\n  const started = Date.now();\n  return new Promise<void>(resolve => {\n    const [command, ...args] = entry.check.argv;\n    const child = spawn(command, args, {\n      cwd,\n      env: gateEnv,\n      stdio: ['ignore', fd, fd],\n      detached: ownGroup,\n    });\n    current = { entry, child, started };\n    entry.outcome = { kind: 'running' };\n    render(entries);\n    // A command that cannot be spawned reports `error` and may or may not also\n    // report `close`; whichever settles the check first wins.\n    let settled = false;\n    const settle = (outcome: Outcome): void => {\n      if (settled) return;\n      settled = true;\n      current = null;\n      closeSync(fd);\n      entry.seconds = (Date.now() - started) / 1000;\n      if (entry.outcome.kind === 'running') entry.outcome = outcome;\n      resolve();\n    };\n    child.once('error', error => {\n      settle({ kind: 'not-started', error: error.message });\n    });\n    child.once('close', (exitCode, signal) => {\n      settle(exitCode === 0 ? { kind: 'passed' } : { kind: 'failed', exitCode, signal });\n    });\n  });\n}\n\ninterface Result {\n  status: 'green' | 'red' | 'incomplete';\n  summary: string;\n}\n\nasync function runGate(): Promise<Result> {\n  const stoppedGroups = new Set<string>();\n  for (const entry of entries) {\n    if (stoppedGroups.has(entry.check.group)) continue;\n    await runOne(entry);\n    if (entry.outcome.kind !== 'passed') stoppedGroups.add(entry.check.group);\n  }\n  render(entries);\n\n  const failures = entries.filter(entry => entry.outcome.kind === 'failed');\n  const unstarted = entries.find(entry => entry.outcome.kind === 'not-started');\n  const passed = entries\n    .filter(entry => entry.outcome.kind === 'passed')\n    .map(entry => entry.check.name);\n  const ranPassed = passed.length === 0 ? 'No check passed.' : `Passed: ${passed.join(', ')}.`;\n\n  const failed = failures.map(entry => `${entry.check.name} ${describe(entry.outcome)}`).join('; ');\n  // A check that could not start leaves part of the gate unrun, so the result is\n  // unfinished even when another group failed: a red verdict would read as complete.\n  if (unstarted !== undefined) {\n    return {\n      status: 'incomplete',\n      summary: `${unstarted.check.name} ${describe(unstarted.outcome)}. ${ranPassed} Later checks in its group never ran.${failed === '' ? '' : ` Failed: ${failed}.`}`,\n    };\n  }\n  if (failures.length > 0) return { status: 'red', summary: `${failed}. ${ranPassed} See validation.md.` };\n  if (entries.length === 0) {\n    return { status: 'green', summary: `No checks defined by this project. ${discovery.notes}`.trim() };\n  }\n  return { status: 'green', summary: `Every check passed: ${passed.join(', ')}.` };\n}\n\nmkdirSync(logDir, { recursive: true });\nemit(await runGate());\n"},"scripts":{"__archon_pack__bundled:sdlc:deliver::outcome":{"path":"deliver/scripts/outcome.ts","runtime":"bun"},"__archon_pack__bundled:sdlc:deliver::report":{"path":"deliver/scripts/report.ts","runtime":"bun"},"__archon_pack__bundled:sdlc:deliver::round":{"path":"deliver/scripts/round.ts","runtime":"bun"},"__archon_pack__bundled:sdlc:implement::assert-changed":{"path":"implement/scripts/assert-changed.ts","runtime":"bun"},"__archon_pack__bundled:sdlc:intake::facts":{"path":"intake/scripts/facts.ts","runtime":"bun"},"__archon_pack__bundled:sdlc:intake::outcome":{"path":"intake/scripts/outcome.ts","runtime":"bun"},"__archon_pack__bundled:sdlc:investigate::verdict":{"path":"investigate/scripts/verdict.ts","runtime":"bun"},"__archon_pack__bundled:sdlc:pr::publish-pr":{"path":"pr/scripts/publish-pr.ts","runtime":"bun"},"__archon_pack__bundled:sdlc:review::prune-scratch":{"path":"review/scripts/prune-scratch.ts","runtime":"bun"},"__archon_pack__bundled:sdlc:review::publish-review":{"path":"review/scripts/publish-review.ts","runtime":"bun"},"__archon_pack__bundled:sdlc:review::review-round":{"path":"review/scripts/review-round.ts","runtime":"bun"},"__archon_pack__bundled:sdlc:ship::outcome":{"path":"ship/scripts/outcome.ts","runtime":"bun"},"__archon_pack__bundled:sdlc:ship::report":{"path":"ship/scripts/report.ts","runtime":"bun"},"__archon_pack__bundled:sdlc:simplify::prune-scratch":{"path":"simplify/scripts/prune-scratch.ts","runtime":"bun"},"__archon_pack__bundled:sdlc:triage::policy":{"path":"triage/scripts/policy.ts","runtime":"bun"},"__archon_pack__bundled:sdlc:triage::verdict":{"path":"triage/scripts/verdict.ts","runtime":"bun"},"__archon_pack__bundled:sdlc:upkeep::outcome":{"path":"upkeep/scripts/outcome.ts","runtime":"bun"},"__archon_pack__bundled:sdlc:validate::compare":{"path":"validate/scripts/compare.ts","runtime":"bun"},"__archon_pack__bundled:sdlc:validate::mode":{"path":"validate/scripts/mode.ts","runtime":"bun"},"__archon_pack__bundled:sdlc:validate::result":{"path":"validate/scripts/result.ts","runtime":"bun"},"__archon_pack__bundled:sdlc:validate::run-checks":{"path":"validate/scripts/run-checks.ts","runtime":"bun"}}},
};
